-- بيانات مقرر كيمياء 1 (المقرر 2، قيد الإعداد) — الجزء 5 من 5. نفّذ الأجزاء بالترتيب.
-- مولّد آليًا بواسطة scripts/build-chem1-seed.js — لا تعدّله يدويًا.
begin;
insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K1-C5-L2-O04'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما الفرق الصحيح بين الكتلة الذرية والكتلة المولية لعنصر ما؟', null, '["الكتلة الذرية تخص ذرة واحدة وتُقاس بوحدة amu، والكتلة المولية تخص عدد أفوجادرو من الذرات وتُقاس بوحدة g/mol","الكتلة الذرية تخص عدد أفوجادرو من الذرات وتُقاس بوحدة g/mol، والكتلة المولية تخص ذرة واحدة وتُقاس بوحدة amu","الكتلة الذرية والكتلة المولية تخصان ذرة واحدة، ويختلفان في الوحدة فقط","الكتلة الذرية تخص ذرة واحدة وتساوي عدديًّا الكتلة المولية، وكلتاهما تُقاس بوحدة amu"]'::jsonb, 'فهم', 'تمييز بين مفهومين', 'سهل', 'الكتاب ص 161، 167 — الكتلة المولية'),
('mcq', 2, 'كتب طالب أن الكتلة المولية للصوديوم Na تساوي 22.99 amu. ما التصحيح الصحيح لهذه العبارة؟', null, '["الكتلة المولية للصوديوم تساوي 1.38×10²⁵ amu لأنها تخص عدد أفوجادرو من الذرات","الكتلة المولية للصوديوم تساوي 22.99 g لأنها تُقاس بالجرام فقط","الكتلة المولية للصوديوم تساوي 22.99 g/mol؛ فالقيمة صحيحة والوحدة amu وحدة الكتلة الذرية","الكتلة المولية للصوديوم تساوي 22.99 mol/g؛ فالقيمة صحيحة والوحدة مقلوبة"]'::jsonb, 'فهم', 'تصحيح عبارة خاطئة في الوحدة', 'متوسط', 'الكتاب ص 161، 162 — الكتلة المولية والكتلة الذرية'),
('mcq', 3, 'كتلة 1 mol من ذرات الكربون-12 تساوي 12 g. ما كتلة ذرة كربون-12 واحدة بوحدة الجرام؟', null, '["تساوي 12 g","تساوي 1.99×10⁻²³ g","تساوي 7.22×10²⁴ g","تساوي 5.02×10²² g"]'::jsonb, 'تطبيق', 'حساب كتلة ذرة بالجرام', 'متوسط', 'الكتاب ص 161 — مختبر حل المشكلات (الكربون-12)'),
('mcq', 4, 'لماذا تساوي الكتلة المولية لأي عنصر كتلته الذرية عدديًّا؟', null, '["لأن الكتلة المولية هي كتلة ذرة واحدة نفسها لكنها مقيسة بوحدة مختلفة","لأن عدد أفوجادرو يساوي 1 عند التحويل بين وحدتي amu وg","لأن لجميع العناصر العدد نفسه من البروتونات والنيوترونات في ذراتها","لأن كتل الذرات حُدّدت نسبةً إلى ذرة الكربون-12، والمول هو عدد الذرات في 12 g منه"]'::jsonb, 'فهم', 'تفسير', 'صعب', 'الكتاب ص 161 — الكتلة المولية (الكربون-12)'),
('mcq', 5, 'الكتلة الذرية للمغنيسيوم Mg تساوي 24.31 amu. أيّ العبارات الآتية صحيحة؟', null, '["كتلة 6.02×10²³ ذرة منه تساوي 24.31 g","كتلة ذرة واحدة منه تساوي 24.31 g","كتلة 6.02×10²³ ذرة منه تساوي 24.31 amu","كتلة ذرتين منه تساوي 24.31 g/mol"]'::jsonb, 'فهم', 'ربط الكتلة الذرية بالكتلة المولية', 'سهل', 'الكتاب ص 161، 167 — الكتلة المولية'),
('mcq', 6, 'كتلة 1 mol من ذرات النحاس أكبر من كتلة ذرة نحاس واحدة بكم مرة، إذا عُبِّر عن الكتلتين بالوحدة نفسها؟', null, '["بمقدار 63.546 مرة","بمقدار 6.02×10²³ مرة","مرة واحدة؛ القيمتان متساويتان","بمقدار 6.02×10⁻²³ مرة"]'::jsonb, 'تحليل', 'مقارنة كتلة ذرة بكتلة مول', 'صعب', 'الكتاب ص 161، 167 — الكتلة المولية'),
('mcq', 7, 'تبيّن البيانات الآتية قيمتين لعنصر النيون Ne. ما اسم كل من القيمتين (أ) و(ب)؟', '{"headers":["العنصر","القيمة (أ)","القيمة (ب)"],"rows":[["Ne","20.18 amu","20.18 g/mol"]]}'::jsonb, '["(أ) الكتلة المولية، و(ب) الكتلة الذرية","(أ) و(ب) كلتاهما كتلة ذرية؛ فالقيمتان تعبّران عن الكمية نفسها","(أ) الكتلة الذرية، و(ب) الكتلة المولية","(أ) و(ب) كلتاهما كتلة مولية؛ فالوحدتان متكافئتان"]'::jsonb, 'فهم', 'تسمية كميتين من الوحدات', 'سهل', 'الكتاب ص 161، 180 — الكتلة المولية والكتلة الذرية'),
('essay', 1, 'وضّح الفرق بين الكتلة الذرية والكتلة المولية لعنصر ما من حيث: عدد الذرات التي تخصها كل منهما، ووحدة القياس، والقيمة العددية، مستعينًا بمثال الحديد الذي كتلته الذرية 55.845 amu.', null, null, 'فهم', 'توضيح الفرق بين مفهومين', 'متوسط', 'الكتاب ص 161، 167، 180 — الكتلة الذرية والكتلة المولية'),
('essay', 2, 'كتلة 1 mol من ذرات الكربون-12 تساوي 12 g تمامًا، وكتلة ذرة الكربون-12 الواحدة تساوي 12 amu. (أ) احسب كتلة ذرة كربون-12 واحدة بوحدة g. (ب) استنتج كتلة 1 amu بوحدة g. (ج) فسّر لماذا تتساوى الكتلة الذرية بوحدة amu مع الكتلة المولية بوحدة g/mol عدديًّا.', null, null, 'تطبيق', 'حساب وتفسير', 'صعب', 'الكتاب ص 161 — مختبر حل المشكلات'),
('essay', 3, 'كتب طالب: «الكتلة المولية للكبريت S تساوي 32.07 amu، وكتلة ذرة الكبريت الواحدة تساوي 32.07 g/mol». حدّد الخطأين في العبارة وصحّحهما، ثم اذكر كتلة 6.02×10²³ ذرة من الكبريت بالوحدة المناسبة.', null, null, 'تقويم', 'تقويم عبارة وتصحيحها', 'صعب', 'الكتاب ص 161، 180 — الكتلة المولية والكتلة الذرية')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K1-C5-L2-O04') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'الكتلة الذرية كتلة ذرة واحدة ووحدتها amu، أما الكتلة المولية فهي كتلة عدد أفوجادرو من الذرات (مول واحد) ووحدتها g/mol، وتتساويان عدديًّا. إذن.', '["","الخيار يعكس الأدوار؛ فـ amu وحدة الكتلة الذرية التي تخص ذرة واحدة، وg/mol وحدة الكتلة المولية التي تخص مولًا من الذرات.","الكتلة المولية لا تخص ذرة واحدة بل مولًا كاملًا من الذرات، وهي تختلف عن الكتلة الذرية في الكمية المقصودة لا في الوحدة فقط.","الكتلة المولية لا تُقاس بوحدة amu؛ فوحدتها g/mol، والتساوي بينهما عددي فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.474Z"}'::jsonb),
('mcq', 2, 2, 'القيمة العددية للكتلة المولية تساوي الكتلة الذرية، لكن وحدتها g/mol لا amu؛ فالتصحيح هو أن الكتلة المولية للصوديوم 22.99 g/mol.', '["هذه القيمة ناتجة عن ضرب 22.99 في عدد أفوجادرو؛ وهذا خطأ لأن الكتلة المولية بالجرامات لا بوحدة amu، وتساوي 22.99 g/mol.","الكتلة المولية كتلة لمول واحد فوحدتها g/mol وليست g وحده.","","الوحدة mol/g مقلوبة؛ فالكتلة المولية جرامات لكل مول وليست مولات لكل جرام."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:32:48.475Z"}'::jsonb),
('mcq', 3, 1, 'المول يحوي 6.02×10²³ ذرة، فكتلة الذرة الواحدة = 12 g ÷ 6.02×10²³ = 1.99×10⁻²³ g.', '["هذه كتلة مول كامل من ذرات الكربون-12 (الكتلة المولية) لا كتلة ذرة واحدة.","","هذه القيمة ناتجة عن ضرب 12 في عدد أفوجادرو بدل القسمة عليه.","هذه القيمة ناتجة عن قسمة عدد أفوجادرو على 12، وهي عدد الذرات في 1 g لا كتلة ذرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-18T03:32:48.475Z"}'::jsonb),
('mcq', 4, 3, 'كتل الذرات حُدّدت بالنسبة إلى ذرة الكربون-12 (12 amu)، والمول هو عدد الذرات في 12 g من الكربون-12؛ فنسبة كتلة المول من أي عنصر إلى كتلة مول الكربون-12 تساوي نسبة كتلة ذرته إلى كتلة ذرة الكربون-12، فيتطابق الرقمان.', '["الكتلة المولية ليست كتلة ذرة واحدة؛ فهي كتلة عدد أفوجادرو من الذرات، والتطابق في الرقم يعود إلى تعريف المول والكتلة الذرية بالنسبة إلى الكربون-12.","عدد أفوجادرو يساوي 6.02×10²³ وليس 1؛ وتساوي القيمتان عدديًّا بسبب ربط التعريفين بالكربون-12.","ذرات العناصر تختلف في أعداد بروتوناتها ونيوتروناتها، ولهذا تختلف كتلها الذرية وكتلها المولية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:32:48.475Z"}'::jsonb),
('mcq', 5, 0, '6.02×10²³ ذرة هي مول واحد، وكتلته بالجرامات تساوي عدديًّا الكتلة الذرية، فهي 24.31 g.', '["","كتلة الذرة الواحدة تُقاس بوحدة amu وتساوي 24.31 amu، أما 24.31 g فهي كتلة مول كامل.","كتلة مول من الذرات تُعبَّر عنها بالجرامات؛ والقيمة 24.31 amu هي كتلة ذرة واحدة فقط.","الوحدة g/mol تعبّر عن الكتلة المولية لا عن كتلة ذرتين؛ وكتلة ذرتين تساوي 48.62 amu."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.475Z"}'::jsonb),
('mcq', 6, 1, 'المول الواحد يضم 6.02×10²³ ذرة متماثلة، فكتلته أكبر من كتلة ذرة واحدة بمقدار 6.02×10²³ مرة. وتساوي القيمتان عدديًّا (63.546) لاختلاف الوحدتين فقط (amu وg).', '["العدد 63.546 هو القيمة العددية لكل من الكتلتين، وليس نسبة بينهما.","","التساوي العددي ناتج عن اختلاف الوحدتين (amu وg)؛ فإذا عُبّر عنهما بوحدة واحدة اختلفت الكتلتان بعدد أفوجادرو.","هذه النسبة مقلوبة؛ فكتلة المول أكبر من كتلة ذرة واحدة لا أصغر منها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:32:48.475Z"}'::jsonb),
('mcq', 7, 2, 'الوحدة amu هي وحدة الكتلة الذرية (كتلة ذرة واحدة)، والوحدة g/mol هي وحدة الكتلة المولية (كتلة مول واحد)؛ إذن (أ) كتلة ذرية و(ب) كتلة مولية.', '["الاسمان معكوسان؛ فالوحدة amu تخص الكتلة الذرية، والوحدة g/mol تخص الكتلة المولية.","الوحدتان مختلفتان، فهما كميتان مختلفتان: إحداهما لذرة واحدة والأخرى لمول من الذرات، وإن تساوتا عدديًّا.","","الوحدتان غير متكافئتين؛ فـ amu وحدة كتلة ذرة واحدة، أما g/mol فوحدة كتلة مول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-18T03:32:48.475Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الكتلة الذرية هي كتلة ذرة واحدة من العنصر ووحدتها amu، أما الكتلة المولية فهي كتلة مول واحد من العنصر، أي كتلة عدد أفوجادرو (6.02×10²³) من ذراته، ووحدتها g/mol. وتتساوى الكتلتان عدديًّا. ففي الحديد: كتلة ذرة واحدة 55.845 amu، وكتلة 1 mol منه (6.02×10²³ ذرة) 55.845 g، فكتلته المولية 55.845 g/mol.', '["الكتلة الذرية تخص ذرة واحدة، والمولية تخص عدد أفوجادرو من الذرات","وحدة الكتلة الذرية amu ووحدة الكتلة المولية g/mol","القيمتان متساويتان عدديًّا","الحديد: 55.845 amu و55.845 g/mol"]'::jsonb, '[]'::jsonb, '[{"element":"اختلاف عدد الذرات التي تخصها كل منهما","marks":1},{"element":"اختلاف الوحدتين amu وg/mol","marks":1},{"element":"التساوي العددي","marks":1},{"element":"تطبيق ذلك على الحديد","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"عرض الفروق الثلاثة بدقة مع مثال الحديد"},{"level":"2–3 درجات","description":"عرض فرقين أو ثلاثة مع نقص في المثال"},{"level":"1 درجة","description":"ذكر فرق واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الكتلة المولية تخص ذرة واحدة","كتابة الوحدة amu للكتلة المولية","القول إن القيمتين العدديتين مختلفتان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.476Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) كتلة الذرة الواحدة = 12 g ÷ 6.02×10²³ ذرة = 1.99×10⁻²³ g. (ب) لأن هذه الكتلة تساوي 12 amu فإن 1 amu = 1.99×10⁻²³ g ÷ 12 = 1.66×10⁻²⁴ g. (ج) كتلة مول واحد من أي عنصر = كتلة ذرته بوحدة amu × 6.02×10²³ × 1.66×10⁻²⁴ g/amu ≈ كتلة ذرته بوحدة amu × 1.00 g؛ فالعدد الذي يعبّر عن كتلة الذرة بوحدة amu هو نفسه الذي يعبّر عن كتلة المول بوحدة g.', '["كتلة الذرة بالجرام = 12 ÷ 6.02×10²³ = 1.99×10⁻²³ g","1 amu = 1.66×10⁻²⁴ g","حاصل ضرب 1.66×10⁻²⁴ g في 6.02×10²³ يساوي 1 g تقريبًا","لذلك تتساوى القيمتان عدديًّا ويختلف المعنى والوحدة"]'::jsonb, '["كتلة الذرة بالجرام = 12 g/mol ÷ 6.02×10²³ ذرة/mol = 1.99×10⁻²³ g","1 amu = 1.99×10⁻²³ g ÷ 12 = 1.66×10⁻²⁴ g","1 amu × 6.02×10²³ = 1.66×10⁻²⁴ g × 6.02×10²³ ≈ 1.00 g"]'::jsonb, '[{"element":"كتلة ذرة الكربون-12 بالجرام 1.99×10⁻²³ g","marks":1},{"element":"حساب 1 amu بالجرام","marks":2},{"element":"ضرب 1 amu في عدد أفوجادرو للحصول على 1 g تقريبًا","marks":1},{"element":"استنتاج التساوي العددي مع اختلاف الوحدة والمعنى","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الحسابات الثلاثة صحيحة مع استنتاج صحيح"},{"level":"3–4 درجات","description":"حسابان صحيحان مع تفسير ناقص"},{"level":"1–2 درجة","description":"حساب واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب 12 في عدد أفوجادرو بدل قسمته عليه","اعتبار كتلة الذرة بالجرام تساوي 12 g","القول إن 1 amu يساوي 1 g"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-18T03:32:48.476Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الخطأ الأول: وُصفت الكتلة المولية بوحدة amu، والصحيح أن الكتلة المولية للكبريت 32.07 g/mol. الخطأ الثاني: وُصفت كتلة الذرة الواحدة بوحدة g/mol، والصحيح أن كتلة ذرة الكبريت الواحدة (كتلته الذرية) 32.07 amu. أما كتلة 6.02×10²³ ذرة (مول واحد) فتساوي 32.07 g.', '["الكتلة المولية وحدتها g/mol لا amu: 32.07 g/mol","كتلة الذرة الواحدة (الكتلة الذرية) وحدتها amu لا g/mol: 32.07 amu","كتلة 6.02×10²³ ذرة تساوي 32.07 g"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد خطأ وحدة الكتلة المولية وتصحيحه","marks":1},{"element":"تحديد خطأ وحدة الكتلة الذرية وتصحيحه","marks":1},{"element":"كتلة 6.02×10²³ ذرة تساوي 32.07 g","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تحديد الخطأين وتصحيحهما وذكر كتلة المول بالوحدة الصحيحة"},{"level":"2 درجتان","description":"تحديد خطأ واحد وتصحيحه مع ذكر كتلة المول"},{"level":"1 درجة","description":"ذكر كتلة المول فقط أو تحديد خطأ واحد دون تصحيحه"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصحيح القيمة العددية بدل الوحدة","القول إن كتلة 6.02×10²³ ذرة تساوي 32.07 amu","تبديل الوحدتين دون تعليل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-18T03:32:48.476Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
