('mcq', 1, 'عيّنتان: الأولى 1.00 mol من الألمنيوم Al (كتلته المولية 26.98 g/mol)، والثانية 1.00 mol من الرصاص Pb (كتلته المولية 207.2 g/mol). أيّ المقارنات الآتية صحيحة؟', null, '["عيّنة الرصاص تحوي ذرات أكثر لأن كتلتها أكبر","العيّنتان تحويان العدد نفسه من الذرات، لكن كتلة عيّنة الرصاص أكبر","عيّنة الألمنيوم تحوي ذرات أكثر لأن ذراتها أخف كتلة","العيّنتان لهما الكتلة نفسها لأنهما تحويان العدد نفسه من الذرات"]'::jsonb, 'فهم', 'مقارنة مولين من مادتين', 'سهل', 'الكتاب ص 160، 161 — كتلة المول'),
('mcq', 2, 'عيّنة من الليثيوم Li كتلتها 10.0 g (كتلته المولية 6.94 g/mol)، وعيّنة من الصوديوم Na مقدارها 1.00 mol. أيّ العبارات الآتية صحيحة؟', null, '["عيّنة الصوديوم تحوي ذرات أكثر لأن كتلة مولها أكبر من كتلة مول الليثيوم","لا يمكن المقارنة بين العيّنتين لأن إحداهما معلومة بالجرامات والأخرى بالمولات","العيّنتان تحويان العدد نفسه من الذرات لأن كمية كل منهما تقارب الأخرى","عيّنة الليثيوم تحوي ذرات أكثر لأن 10.0 g منه تساوي 1.44 mol وهي أكثر من 1.00 mol"]'::jsonb, 'تحليل', 'مقارنة عدد الذرات بتحويل الكتلة إلى مولات', 'متوسط', 'الكتاب ص 160، 167، 181 — مقارنة المولات والكتل'),
('mcq', 3, 'رتّب العيّنات الآتية تصاعديًّا بحسب الكتلة: (A) 0.500 mol من المغنيسيوم Mg (24.31 g/mol)، (B) 6.02×10²² ذرة من الحديد Fe (55.85 g/mol)، (C) 15.0 g من الكبريت S.', null, '["B < A < C","B < C < A","A < C < B","A < B < C"]'::jsonb, 'تحليل', 'ترتيب كميات مختلفة الوحدات بحسب الكتلة', 'صعب', 'الكتاب ص 181 — ترتيب الكميات بحسب الكتلة'),
('mcq', 4, 'أُخذت من كل عنصر في البيانات الآتية عيّنة كتلتها 20.0 g. أيّ العيّنات تحوي أكبر عدد من الذرات؟', '{"headers":["العنصر","الكتلة المولية (g/mol)"],"rows":[["Mg","24.31"],["K","39.10"],["Na","22.99"],["Ca","40.08"]]}'::jsonb, '["عيّنة المغنيسيوم Mg","عيّنة البوتاسيوم K","عيّنة الصوديوم Na","عيّنة الكالسيوم Ca"]'::jsonb, 'تحليل', 'مقارنة عدد الذرات لعيّنات متساوية الكتلة', 'سهل', 'الكتاب ص 160، 181 — مقارنة المولات والكتل'),
('mcq', 5, 'الكتلة المولية للكبريت S تساوي 32.07 g/mol، وللأكسجين O تساوي 16.00 g/mol. كم مرة تقريبًا تزيد كتلة ذرة كبريت واحدة على كتلة ذرة أكسجين واحدة؟', null, '["مرة واحدة تقريبًا","2.00 مرة تقريبًا","0.500 مرة تقريبًا","6.02×10²³ مرة تقريبًا"]'::jsonb, 'تحليل', 'استنتاج نسبة كتل الذرات من كتل المولات', 'سهل', 'الكتاب ص 160، 161 — لماذا تختلف كتل المولات'),
('mcq', 6, 'أيّ عيّنات النحاس Cu الآتية لها أكبر كتلة؟ (الكتلة المولية للنحاس 63.55 g/mol)', null, '["80.0 g","6.02×10²³ ذرة","0.900 mol","1.50 mol"]'::jsonb, 'تحليل', 'مقارنة كميات من العنصر نفسه بوحدات مختلفة', 'متوسط', 'الكتاب ص 181 — مقارنة الكميات بتحويلها إلى كتلة'),
('mcq', 7, 'تبيّن البيانات الآتية ثلاث عيّنات X وY وZ، كل منها عنصر نقي مختلف. أيّ الاستنتاجات الآتية صحيح؟', '{"headers":["العيّنة","عدد الذرات","الكتلة"],"rows":[["X","6.02×10²³ ذرة","7.00 g"],["Y","6.02×10²³ ذرة","28.0 g"],["Z","3.01×10²³ ذرة","14.0 g"]]}'::jsonb, '["ذرات X أثقل من ذرات Z لأن عدد ذرات X أكبر","ذرات Z أخف من ذرات Y لأن كتلة العيّنة Z أقل","ذرات Y وZ لها الكتلة نفسها لأن كتلة مول من كل منهما 28.0 g","ذرات X وY لها الكتلة نفسها لأن عدد الذرات في العيّنتين متساوٍ"]'::jsonb, 'تحليل', 'استنتاج من بيانات عدد الذرات والكتلة', 'متوسط', 'الكتاب ص 160، 161، 167 — كتلة المول وعدد الذرات'),
('essay', 1, 'قارن بين 1 mol من المغنيسيوم Mg (24.31 g/mol) و1 mol من الكالسيوم Ca (40.08 g/mol) من حيث عدد الذرات والكتلة، ثم احسب كم مرة تقريبًا تزيد كتلة ذرة الكالسيوم على كتلة ذرة المغنيسيوم، مفسّرًا سبب اختلاف كتلتي المولين.', null, null, 'تحليل', 'مقارنة وتفسير مع حساب', 'متوسط', 'الكتاب ص 160، 161 — كتلة المول'),
('essay', 2, 'تتوفر أربع عيّنات: (A) 0.250 mol من الرصاص Pb (207.2 g/mol)، (B) 1.20×10²⁴ ذرة من النحاس Cu (63.55 g/mol)، (C) 25.0 g من الصوديوم Na (22.99 g/mol)، (D) 1.00 mol من الهيليوم He (4.00 g/mol). رتّب العيّنات تصاعديًّا (أ) بحسب عدد الذرات، و(ب) بحسب الكتلة، موضّحًا حساباتك، وفسّر لماذا لا يتطابق الترتيبان.', null, null, 'تحليل', 'ترتيب كميات مختلفة بمعيارين', 'صعب', 'الكتاب ص 181 — ترتيب الكميات بحسب الكتلة وعدد المولات'),
('essay', 3, 'عند شراء دزينة من البيض ودزينة من الليمون يكون العدد واحدًا لكن الكتلتين مختلفتان. استعن بهذه الفكرة لتفسّر لماذا تختلف كتلة مول من الكربون (12.01 g/mol) عن كتلة مول من النحاس (63.55 g/mol)، ثم احسب أيّ العيّنتين تحوي ذرات أكثر إذا كانت كتلة كل منهما 10.0 g، وكم مرة تقريبًا يزيد عدد ذرات إحداهما على الأخرى.', null, null, 'تقويم', 'تفسير بتشبيه ثم مقارنة حسابية', 'صعب', 'الكتاب ص 160 — كتلة المول (دزينة البيض والليمون)')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
