from (values
('mcq', 1, 1, 'المول من أي مادة يحوي العدد نفسه من الجسيمات (6.02×10²³ ذرة)، لكن كتلته تختلف باختلاف المادة؛ فكتلة 1.00 mol من Pb هي 207.2 g وكتلة 1.00 mol من Al هي 26.98 g. إذن العيّنتان تحويان العدد نفسه من الذرات وكتلة الرصاص أكبر.', '["عدد الذرات يحدده عدد المولات لا الكتلة؛ وبما أن العيّنتين متساويتان في المولات فعدد ذراتهما متساوٍ.","","خفة ذرة الألمنيوم لا تزيد عدد ذراته في مول؛ فالمول يحوي 6.02×10²³ ذرة من أي عنصر.","تساوي عدد الذرات لا يعني تساوي الكتلة؛ فكتلة الذرة تختلف من عنصر إلى آخر، وبالتالي تختلف كتلة المول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.477Z"}'::jsonb),
('mcq', 2, 3, 'عدد الذرات يتناسب مع عدد المولات؛ وعدد مولات الليثيوم = 10.0 g ÷ 6.94 g/mol = 1.44 mol وهو أكبر من 1.00 mol من الصوديوم، فعيّنة الليثيوم تحوي ذرات أكثر.', '["كبر الكتلة المولية لا يعني كثرة الذرات؛ فعدد الذرات يتبع عدد المولات، وهو هنا 1.00 mol للصوديوم مقابل 1.44 mol لليثيوم.","يمكن المقارنة بتحويل الكتلة إلى مولات؛ فالمول هو الأساس المشترك لعدّ الذرات.","عدد المولات في العيّنتين غير متساوٍ (1.44 mol و1.00 mol)، فعدد الذرات غير متساوٍ.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.477Z"}'::jsonb),
('mcq', 3, 0, 'نحوّل كل عيّنة إلى جرامات: (A) 0.500 mol × 24.31 = 12.2 g، (B) 6.02×10²² ذرة = 0.100 mol فكتلتها 0.100 × 55.85 = 5.59 g، (C) 15.0 g. الترتيب التصاعدي: B (5.59 g) < A (12.2 g) < C (15.0 g).', '["","هذا الترتيب بحسب عدد المولات (B: 0.100 mol، C: 0.468 mol، A: 0.500 mol) وليس بحسب الكتلة؛ فكتل المولات تختلف باختلاف المادة.","هذا الترتيب بحسب الكتلة المولية للعناصر (24.31 < 32.06 < 55.85) وليس كتلة العيّنات المعطاة.","هذا ترتيب ذكر العيّنات في السؤال دون حساب الكتل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:32:48.477Z"}'::jsonb),
('mcq', 4, 2, 'عدد الذرات يتناسب مع عدد المولات، وعدد المولات = 20.0 g ÷ الكتلة المولية: Mg ‏0.823 mol، وK ‏0.512 mol، وNa ‏0.870 mol، وCa ‏0.499 mol. أكبرها الصوديوم؛ لأن كتلته المولية أصغر.', '["المغنيسيوم 0.823 mol وهو أقل من الصوديوم (0.870 mol)، فعدد ذراته أقل.","البوتاسيوم 0.512 mol فقط؛ فالعنصر الأثقل ذرةً يعطي مولات أقل لكتلة معينة.","","الكالسيوم له أكبر كتلة مولية (40.08 g/mol)، فتعطي كتلة 20.0 g منه أقل عدد من المولات (0.499 mol)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.478Z"}'::jsonb),
('mcq', 5, 1, 'المول من كل عنصر يحوي العدد نفسه من الذرات، فنسبة كتلتي الذرتين تساوي نسبة كتلتي المولين: 32.07 ÷ 16.00 = 2.00. إذن كتلة ذرة S تساوي نحو 2.00 مرة كتلة ذرة O.', '["تساوي عدد الذرات في المولين لا يعني تساوي كتلتي الذرتين؛ فكتلتا المولين مختلفتان (32.07 g و16.00 g).","","هذه النسبة مقلوبة (16.00 ÷ 32.07)؛ فذرة الكبريت أثقل من ذرة الأكسجين لا أخف.","عدد أفوجادرو هو عدد الذرات في المول وليس نسبة بين كتلتي ذرتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.478Z"}'::jsonb),
('mcq', 6, 3, 'نحوّل كل كمية إلى جرامات: 80.0 g، و6.02×10²³ ذرة = 1.00 mol = 63.55 g، و0.900 mol = 57.2 g، و1.50 mol = 95.3 g. أكبرها 1.50 mol.', '["80.0 g أقل من 95.3 g؛ والعدد 80.0 يبدو أكبر من 1.50 لأن الوحدتين مختلفتان فقط.","6.02×10²³ ذرة تساوي 1.00 mol أي 63.55 g؛ والعدد الكبير لا يعني الكتلة الأكبر لأن الوحدة مختلفة.","0.900 mol تساوي 57.2 g وهي أقل من 95.3 g.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:32:48.478Z"}'::jsonb),
('mcq', 7, 2, 'العيّنة Y مول واحد كتلته 28.0 g، والعيّنة Z نصف مول (3.01×10²³ ÷ 6.02×10²³ = 0.500 mol) وكتلته 14.0 g، أي أن كتلة المول 14.0 ÷ 0.500 = 28.0 g أيضًا؛ فذرات Y وZ لها الكتلة نفسها.', '["كتلة ذرات X أقل من Z؛ فكتلة مول X هي 7.00 g فقط مقابل 28.0 g لـ Z، وعدد الذرات الأكبر لا يعني ذرات أثقل.","كتلة العيّنة Z أقل لأنها تحوي نصف عدد الذرات فقط، أما كتلة المول منها فهي 28.0 g مثل Y.","","تساوي عدد الذرات في X وY لا يعني تساوي كتلتيهما؛ فكتلة مول X هي 7.00 g وكتلة مول Y هي 28.0 g."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.478Z"}'::jsonb),
('essay', 1, null::int, null, null, 'كلا المولين يحوي العدد نفسه من الذرات (6.02×10²³ ذرة)، لكن كتلة مول Ca (40.08 g) أكبر من كتلة مول Mg (24.31 g). وسبب اختلاف الكتلتين أن كتلة ذرة الكالسيوم أكبر من كتلة ذرة المغنيسيوم مع تساوي عدد الذرات. ونسبة كتلتي الذرتين تساوي نسبة كتلتي المولين: 40.08 ÷ 24.31 = 1.65؛ أي أن ذرة Ca أثقل من ذرة Mg بنحو 1.65 مرة.', '["عدد الذرات متساوٍ في المولين (6.02×10²³)","كتلة مول Ca أكبر: 40.08 g مقابل 24.31 g","السبب: كتلة ذرة Ca أكبر من كتلة ذرة Mg","النسبة 40.08 ÷ 24.31 = 1.65 مرة"]'::jsonb, '["نسبة كتلة ذرة Ca إلى كتلة ذرة Mg = كتلة مول Ca ÷ كتلة مول Mg","40.08 g ÷ 24.31 g = 1.65"]'::jsonb, '[{"element":"تساوي عدد الذرات في المولين","marks":1},{"element":"اختلاف الكتلتين: 40.08 g و24.31 g","marks":1},{"element":"تفسير الاختلاف باختلاف كتلة الذرتين","marks":1},{"element":"حساب النسبة 1.65","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة وتفسير صحيح ونسبة صحيحة"},{"level":"2–3 درجات","description":"مقارنة صحيحة مع نقص في التفسير أو الحساب"},{"level":"1 درجة","description":"ذكر تساوي عدد الذرات أو اختلاف الكتلة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المول الأثقل يحوي ذرات أكثر","عكس النسبة (24.31 ÷ 40.08)","تفسير اختلاف الكتلة باختلاف عدد الذرات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.478Z"}'::jsonb),
('essay', 2, null::int, null, null, 'نحوّل كل عيّنة إلى مولات وجرامات. (A): 0.250 mol، كتلتها 0.250 × 207.2 = 51.8 g. (B): 1.20×10²⁴ ÷ 6.02×10²³ = 1.993 mol، كتلتها 1.993 × 63.55 = 127 g. (C): 25.0 ÷ 22.99 = 1.09 mol، كتلتها 25.0 g. (D): 1.00 mol، كتلتها 4.00 g. الترتيب بحسب عدد الذرات (أي المولات): A (0.250) < D (1.00) < C (1.09) < B (1.99). الترتيب بحسب الكتلة: D (4.00 g) < C (25.0 g) < A (51.8 g) < B (127 g). لا يتطابق الترتيبان لأن المول من المواد المختلفة يحوي العدد نفسه من الذرات لكن كتلته تختلف؛ فالرصاص الثقيل ذرةً كتلته كبيرة رغم قلة مولاته، والهيليوم الخفيف كتلته صغيرة رغم أن مولاته أكبر.', '["تحويل جميع العيّنات إلى مولات وإلى جرامات","الترتيب بحسب عدد الذرات: A < D < C < B","الترتيب بحسب الكتلة: D < C < A < B","التفسير: عدد الذرات في المول ثابت بينما كتلة المول تختلف من مادة إلى أخرى"]'::jsonb, '["A: 0.250 mol؛ 0.250 mol × 207.2 g/mol = 51.8 g","B: 1.20×10²⁴ ذرة × (1 mol ÷ 6.02×10²³ ذرة) = 1.993 mol؛ 1.993 mol × 63.55 g/mol = 127 g","C: 25.0 g × (1 mol ÷ 22.99 g) = 1.09 mol","D: 1.00 mol؛ 1.00 mol × 4.00 g/mol = 4.00 g"]'::jsonb, '[{"element":"حساب المولات للعيّنات الأربع","marks":2},{"element":"حساب الكتل للعيّنات الأربع","marks":2},{"element":"الترتيب الصحيح بحسب عدد الذرات","marks":1},{"element":"الترتيب الصحيح بحسب الكتلة","marks":1},{"element":"تفسير عدم تطابق الترتيبين","marks":1}]'::jsonb, '[{"level":"7 درجات","description":"حسابات صحيحة، والترتيبان صحيحان، والتفسير صحيح"},{"level":"5–6 درجات","description":"الترتيبان صحيحان مع خطأ بسيط في الحساب أو نقص في التفسير"},{"level":"3–4 درجات","description":"أحد الترتيبين صحيح فقط، أو حسابات صحيحة دون ترتيب"},{"level":"1–2 درجة","description":"تحويل صحيح لعيّنة أو عيّنتين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ترتيب العيّنات بحسب القيم المعطاة دون تحويل","استعمال ترتيب المولات نفسه للكتل","نسيان أن الذرات تُحوَّل إلى مولات قبل حساب الكتلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (7 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:32:48.479Z"}'::jsonb),
('essay', 3, null::int, null, null, 'كما أن دزينة البيض ودزينة الليمون تحويان العدد نفسه لكن الكتلة تختلف لاختلاف كتلة الواحدة، فإن مول الكربون ومول النحاس يحويان العدد نفسه من الذرات (6.02×10²³) لكن كتلتيهما مختلفتان (12.01 g و63.55 g) لأن كتلة ذرة النحاس أكبر. وعند أخذ 10.0 g من كل منهما: مولات الكربون = 10.0 ÷ 12.01 = 0.833 mol، ومولات النحاس = 10.0 ÷ 63.55 = 0.157 mol. فعيّنة الكربون تحوي ذرات أكثر (نحو 5.01×10²³ ذرة مقابل 9.47×10²² ذرة، باستعمال المولات دون تقريب)، وتزيد عليها بنحو 5.29 مرة (0.8326 ÷ 0.1574).', '["المول يحوي العدد نفسه من الذرات لكن كتلته تختلف باختلاف كتلة الذرة (مثل دزينة البيض والليمون)","مولات C = 0.833 mol ومولات Cu = 0.157 mol","عيّنة الكربون تحوي ذرات أكثر","النسبة نحو 5.29 مرة"]'::jsonb, '["10.0 g C × (1 mol C ÷ 12.01 g C) = 0.833 mol C ؛ عدد الذرات ≈ 5.01×10²³ ذرة (باستعمال المولات دون تقريب)","10.0 g Cu × (1 mol Cu ÷ 63.55 g Cu) = 0.157 mol Cu ؛ عدد الذرات ≈ 9.47×10²² ذرة (باستعمال المولات دون تقريب)","النسبة = 0.8326 mol ÷ 0.1574 mol = 5.29"]'::jsonb, '[{"element":"تفسير اختلاف الكتلة مع تساوي العدد بالتشبيه","marks":1},{"element":"حساب مولات الكربون والنحاس","marks":2},{"element":"تحديد العيّنة الأكثر ذرات","marks":1},{"element":"حساب النسبة بين عدديهما","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تفسير صحيح وحسابات صحيحة واستنتاج ونسبة صحيحان"},{"level":"3–4 درجات","description":"تفسير صحيح وحسابات ناقصة أو نسبة خاطئة"},{"level":"1–2 درجة","description":"تفسير جزئي فقط، أو حساب مولات لعيّنة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن عيّنة النحاس أكثر ذرات لأن كتلة مولها أكبر","نسبة معكوسة (0.157 ÷ 0.833)","الخلط بين تساوي الكتلة وتساوي عدد الذرات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:32:48.479Z"}'::jsonb)
