('mcq', 3, 'افترض أن كأس ماء يحوي نحو 8×10²⁴ جزيء، وأن عدد الكؤوس المماثلة المتوفرة على الأرض نحو 4×10²¹ كأس، وأن الماء اختلط تمامًا. كم جزيئًا تقريبًا من جزيئات الكأس الأولى ستوجد في كأس ثانية؟', null, '["نحو 8×10²⁴ جزيء","نحو 2×10³ جزيء","نحو 3.2×10⁴⁶ جزيء","نحو 5×10⁻⁴ جزيء"]'::jsonb, 'تطبيق', 'تقدير بالقسمة على عدد الكؤوس', 'متوسط', 'الكتاب ص 176، 177 — الحاوية العملاقة'),
('mcq', 4, 'أيّ الخطوات الآتية تصف الطريقة الصحيحة لتقدير عدد جزيئات الماء في كأس معلومة كتلة الماء فيها؟', null, '["ضرب الكتلة في الكتلة المولية 18 g/mol، ثم قسمة الناتج على 6.02×10²³","ضرب الكتلة في 6.02×10²³، ثم ضرب الناتج في الكتلة المولية 18 g/mol","قسمة الكتلة المولية 18 g/mol على الكتلة، ثم قسمة الناتج على 6.02×10²³","قسمة الكتلة على الكتلة المولية 18 g/mol لحساب المولات، ثم ضرب الناتج في 6.02×10²³"]'::jsonb, 'فهم', 'اختيار خطوات التقدير', 'سهل', 'الكتاب ص 176 — التحويل من الجرامات إلى مولات ثم جزيئات'),
('mcq', 5, 'باستعمال التقريب 6×10²³ لعدد أفوجادرو و18 g/mol للكتلة المولية للماء، قدّر عدد جزيئات الماء في كوب يحوي 360 g من الماء.', null, '["1.2×10²⁵ جزيء","2.2×10²⁶ جزيء","3×10²² جزيء","3.3×10⁻²³ جزيء"]'::jsonb, 'تطبيق', 'تقدير بتقريب الأعداد', 'سهل', 'الكتاب ص 176 — التاريخ في كأس ماء'),
('mcq', 6, 'إبريق يحوي 2.0 kg من الماء. قدّر عدد جزيئات الماء فيه، علمًا أن الكتلة المولية للماء 18 g/mol.', null, '["6.7×10²² جزيء","1.2×10²⁷ جزيء","5.4×10²¹ جزيء","6.7×10²⁵ جزيء"]'::jsonb, 'تطبيق', 'تقدير عدد الجزيئات مع تحويل الوحدة', 'صعب', 'الكتاب ص 176 — التحويل من الجرامات إلى جزيئات'),
('mcq', 7, 'لماذا يُرجَّح أن يحوي كأس ماء تشربه اليوم بعض جزيئات الماء التي مرّت في جسم شخصية تاريخية قديمة؟', null, '["لأن عدد الكؤوس على الأرض أكبر بكثير من عدد جزيئات الماء في الكأس الواحدة","لأن عدد جزيئات الماء في الكأس الواحدة أكبر بنحو ألف مرة من عدد الكؤوس على الأرض","لأن كتلة مول الماء 18 g فقط، فتحوي الكأس عددًا قليلًا من الجزيئات","لأن جزيئات الماء لا تتفاعل مع غيرها فتبقى في مكانها دون أن تختلط"]'::jsonb, 'فهم', 'تفسير نتيجة تقدير', 'متوسط', 'الكتاب ص 176، 177 — التاريخ في كأس ماء'),
('essay', 1, 'تحوي زجاجة 5.0×10² g من الماء. قدّر عدد جزيئات الماء فيها باستعمال الكتلة المولية 18 g/mol وعدد أفوجادرو 6.02×10²³، ثم تحقق من معقولية الناتج بتقريب الأعداد (6×10²³ و18).', null, null, 'تطبيق', 'تقدير عدد جزيئات مع تحقق', 'متوسط', 'الكتاب ص 176 — التاريخ في كأس ماء'),
('essay', 2, 'قطعة فحم كتلتها 2.4 g، افترض أنها كربون نقي كتلته المولية 12 g/mol. (أ) قدّر عدد ذرات الكربون فيها. (ب) إذا كان عدد سكان الأرض نحو 8×10⁹ نسمة، فكم مرة تقريبًا يزيد عدد ذرات الكربون في القطعة على عدد السكان؟', null, null, 'تطبيق', 'تقدير عدد ذرات ومقارنته بعدد كبير آخر', 'متوسط', 'الكتاب ص 176 — الكتابة في الكيمياء (تقدير الأعداد الكبيرة)'),
('essay', 3, 'كأس يحوي 180 g من الماء، وكتلة الماء الكلية على الأرض نحو 1.4×10²⁴ g، والكتلة المولية للماء 18 g/mol. (أ) احسب عدد جزيئات الماء في الكأس. (ب) احسب عدد الكؤوس المماثلة التي يمكن ملؤها من ماء الأرض. (ج) قارن بين العددين، ثم استنتج كم جزيئًا تقريبًا من جزيئات الكأس الأولى ستكون في كأس ثانية بعد الاختلاط التام للماء.', null, null, 'تقويم', 'تقدير واستنتاج من أعداد كبيرة', 'صعب', 'الكتاب ص 176، 177 — التاريخ في كأس ماء')
