('mcq', 1, 0, 'عدد المولات = 90 g × (1 mol ÷ 18 g) = 5.0 mol، وعدد الجزيئات = 5.0 mol × 6.02×10²³ جزيء/mol = 3.0×10²⁴ جزيء.', '["","هذه القيمة ناتجة عن ضرب 90 في عدد أفوجادرو مباشرة، أي نُسي التحويل إلى مولات بقسمة الكتلة على 18 g/mol.","هذه القيمة ناتجة عن قسمة الكتلة المولية على الكتلة (18 ÷ 90 = 0.2 mol) ثم الضرب في عدد أفوجادرو.","هذه القيمة ناتجة عن قسمة عدد المولات (5.0) على عدد أفوجادرو بدل ضربه فيه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:32:48.480Z"}'::jsonb),
('mcq', 2, 2, 'عدد المولات = 0.050 g × (1 mol ÷ 18 g) = 2.8×10⁻³ mol، وعدد الجزيئات = 2.8×10⁻³ mol × 6.02×10²³ جزيء/mol = 1.7×10²¹ جزيء، أي أن حتى قطرة صغيرة تحوي أعدادًا هائلة من الجزيئات.', '["هذه القيمة ناتجة عن ضرب 0.050 في عدد أفوجادرو مباشرة، أي نُسي القسمة على الكتلة المولية 18 g/mol.","هذه القيمة ناتجة عن قسمة الكتلة المولية على الكتلة (18 ÷ 0.050) ثم الضرب في عدد أفوجادرو، أي عامل التحويل مقلوب.","","هذه القيمة ناتجة عن قسمة عدد المولات على عدد أفوجادرو بدل ضربه فيه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-10-18T03:32:48.480Z"}'::jsonb),
('mcq', 3, 1, 'بعد الاختلاط التام تتوزع جزيئات الكأس الأولى على جميع الكؤوس بالتساوي، فنصيب الكأس الثانية = 8×10²⁴ ÷ 4×10²¹ = 2×10³ جزيء.', '["هذا هو عدد الجزيئات في الكأس الأولى كلها، ولا يمكن أن تحويها الكأس الثانية لأنها تتوزع على جميع الكؤوس.","","هذه القيمة ناتجة عن ضرب عدد الجزيئات في عدد الكؤوس بدل قسمته عليه.","هذه النسبة مقلوبة (4×10²¹ ÷ 8×10²⁴)؛ فعدد الجزيئات أكبر من عدد الكؤوس لا أصغر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-10-18T03:32:48.480Z"}'::jsonb),
('mcq', 4, 3, 'تُحوَّل كتلة الماء أولًا إلى مولات بقسمتها على الكتلة المولية 18 g/mol، ثم تُحوَّل المولات إلى جزيئات بضربها في عدد أفوجادرو 6.02×10²³.', '["الضرب في الكتلة المولية لا يعطي المولات؛ فالمولات تُحسب بالقسمة على الكتلة المولية، والقسمة على عدد أفوجادرو تُنقص الناتج بدل أن تحوّله إلى جزيئات.","لا يوجد تحويل مباشر من الكتلة إلى الجزيئات بالضرب في عدد أفوجادرو، ولا معنى لضرب الناتج في الكتلة المولية.","قسمة الكتلة المولية على الكتلة تعطي كمية مقلوبة لعدد المولات، والقسمة على عدد أفوجادرو تحوّل الجزيئات إلى مولات لا العكس.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-18T03:32:48.480Z"}'::jsonb),
('mcq', 5, 0, 'عدد المولات = 360 g ÷ 18 g/mol = 20 mol، وعدد الجزيئات ≈ 20 mol × 6×10²³ جزيء/mol = 1.2×10²⁵ جزيء.', '["","هذه القيمة ناتجة عن ضرب 360 في 6×10²³ مباشرة، أي نُسي القسمة على 18 g/mol.","هذه القيمة ناتجة عن قسمة 18 على 360 (0.05 mol) ثم الضرب في 6×10²³، أي عامل التحويل مقلوب.","هذه القيمة ناتجة عن قسمة 20 mol على 6×10²³ بدل الضرب فيه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-18T03:32:48.481Z"}'::jsonb),
('mcq', 6, 3, 'نحوّل 2.0 kg إلى 2000 g، ثم عدد المولات = 2000 g ÷ 18 g/mol = 111 mol، وعدد الجزيئات = 111 mol × 6.02×10²³ = 6.7×10²⁵ جزيء.', '["هذه القيمة ناتجة عن استعمال 2.0 g بدل 2000 g، أي نُسي تحويل الكيلوجرام إلى جرام.","هذه القيمة ناتجة عن ضرب 2000 في عدد أفوجادرو مباشرة، أي نُسي القسمة على الكتلة المولية.","هذه القيمة ناتجة عن قسمة الكتلة المولية على الكتلة (18 ÷ 2000) ثم الضرب في عدد أفوجادرو، أي عامل التحويل مقلوب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-10-18T03:32:48.481Z"}'::jsonb),
('mcq', 7, 1, 'كأس الماء يحوي نحو 8×10²⁴ جزيء، وعدد الكؤوس على الأرض نحو 6×10²¹ كأس؛ فعدد الجزيئات في الكأس أكبر بنحو ألف مرة من عدد الكؤوس، فإذا اختلط الماء اختلاطًا تامًّا نال كل كأس نحو ألف جزيء من الكأس الأولى.', '["العلاقة معكوسة؛ فعدد جزيئات الماء في الكأس (نحو 8×10²⁴) أكبر بكثير من عدد الكؤوس (نحو 6×10²¹).","","الكأس تحوي نحو 13 mol من الماء أي أعدادًا هائلة من الجزيئات (نحو 8×10²⁴)، وليس عددًا قليلًا.","جزيئات الماء تتحرك وتختلط في المحيطات والغلاف المائي، ولو لم تختلط لما أمكن أن تتشارك الكؤوس في جزيئاتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:32:48.481Z"}'::jsonb),
('essay', 1, null::int, null, null, 'عدد المولات = 5.0×10² g × (1 mol ÷ 18 g) = 28 mol. عدد الجزيئات = 28 mol × 6.02×10²³ جزيء/mol = 1.7×10²⁵ جزيء. وللتحقق بالتقريب: 500 ÷ 18 ≈ 28 mol و28 × 6×10²³ ≈ 1.7×10²⁵؛ فالناتج معقول، وهو عدد هائل يفوق أي عدد يمكن عدّه مباشرة.', '["تحويل الكتلة إلى مولات: 28 mol","تحويل المولات إلى جزيئات بعدد أفوجادرو","الناتج 1.7×10²⁵ جزيء","التحقق بالتقريب يؤكد معقولية الناتج"]'::jsonb, '["5.0×10² g H₂O × (1 mol H₂O ÷ 18 g H₂O) = 28 mol H₂O","28 mol H₂O × (6.02×10²³ جزيء ÷ 1 mol H₂O) = 1.7×10²⁵ جزيء","التقريب: 28 × 6×10²³ ≈ 1.7×10²⁵"]'::jsonb, '[{"element":"تحويل الكتلة إلى مولات: 28 mol","marks":1},{"element":"تحويل المولات إلى جزيئات","marks":1},{"element":"الناتج 1.7×10²⁵ بالأرقام المعنوية الصحيحة","marks":1},{"element":"التحقق بالتقريب وبيان معقولية الناتج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حل صحيح بخطوتين مع تحقق صحيح بالتقريب"},{"level":"2–3 درجات","description":"حل صحيح دون تحقق، أو خطأ بسيط في أحد الأرقام مع تحقق"},{"level":"1 درجة","description":"حساب المولات فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب الكتلة في عدد أفوجادرو مباشرة","قسمة 18 على الكتلة بدل قسمة الكتلة على 18","كتابة الناتج بعدد خاطئ من الأرقام المعنوية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-18T03:32:48.481Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) عدد المولات = 2.4 g × (1 mol ÷ 12 g) = 0.20 mol، وعدد الذرات = 0.20 mol × 6.02×10²³ ذرة/mol = 1.2×10²³ ذرة. (ب) النسبة = 1.2×10²³ ÷ 8×10⁹ = 1.5×10¹³ مرة تقريبًا؛ أي أن قطعة الفحم الصغيرة تحوي ذرات أكثر من عدد سكان الأرض بنحو خمسة عشر تريليون مرة.', '["عدد المولات 0.20 mol","عدد الذرات 1.2×10²³","قسمة عدد الذرات على عدد السكان","النسبة 1.5×10¹³ مرة تقريبًا"]'::jsonb, '["2.4 g C × (1 mol C ÷ 12 g C) = 0.20 mol C","0.20 mol C × (6.02×10²³ ذرة ÷ 1 mol C) = 1.2×10²³ ذرة","1.2×10²³ ÷ 8×10⁹ = 1.5×10¹³"]'::jsonb, '[{"element":"تحويل الكتلة إلى مولات: 0.20 mol","marks":1},{"element":"عدد الذرات 1.2×10²³","marks":1},{"element":"قسمة عدد الذرات على عدد السكان","marks":1},{"element":"النسبة 1.5×10¹³ بصيغة صحيحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الخطوات الثلاث صحيحة وبالصيغة العلمية الصحيحة"},{"level":"2–3 درجات","description":"حساب عدد الذرات صحيح مع خطأ في المقارنة أو الأس"},{"level":"1 درجة","description":"حساب عدد المولات فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب الكتلة في عدد أفوجادرو دون القسمة على 12","خطأ في طرح الأسس عند قسمة 10²³ على 10⁹","قسمة عدد السكان على عدد الذرات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:32:48.481Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) عدد المولات = 180 g ÷ 18 g/mol = 10 mol، وعدد الجزيئات = 10 mol × 6.02×10²³ = 6.0×10²⁴ جزيء. (ب) عدد الكؤوس = 1.4×10²⁴ g ÷ 180 g/كأس = 7.8×10²¹ كأس. (ج) عدد جزيئات الكأس الواحدة (6.0×10²⁴) أكبر من عدد الكؤوس (7.8×10²¹) بنحو 6.0×10²⁴ ÷ 7.8×10²¹ = 7.7×10² أي ما يقارب ثمانمئة مرة؛ لذلك إذا اختلط الماء تمامًا فستحوي الكأس الثانية نحو 770 جزيئًا مما كان في الكأس الأولى، فمن المرجح أن تتشارك الكؤوس في بعض الجزيئات.', '["عدد المولات في الكأس 10 mol","عدد الجزيئات 6.0×10²⁴","عدد الكؤوس 7.8×10²¹","النسبة نحو 7.7×10² (قرابة 800) ومعناها أن الكأس الثانية تحوي نحو 770 جزيئًا من الأولى"]'::jsonb, '["180 g ÷ 18 g/mol = 10 mol ؛ 10 mol × 6.02×10²³ = 6.0×10²⁴ جزيء","1.4×10²⁴ g × (1 كأس ÷ 180 g) = 7.8×10²¹ كأس","6.0×10²⁴ ÷ 7.8×10²¹ ≈ 7.7×10²"]'::jsonb, '[{"element":"عدد جزيئات الكأس 6.0×10²⁴","marks":1},{"element":"عدد الكؤوس 7.8×10²¹","marks":1},{"element":"النسبة بين العددين 7.7×10²","marks":1},{"element":"الاستنتاج: نحو 770 جزيئًا مشتركًا في الكأس الثانية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحسابات الثلاثة صحيحة مع استنتاج صحيح"},{"level":"2–3 درجات","description":"حسابان صحيحان مع نقص في المقارنة أو الاستنتاج"},{"level":"1 درجة","description":"حساب واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب كتلة الماء الكلية في 180 بدل قسمتها عليه","قسمة عدد الكؤوس على عدد الجزيئات (نسبة مقلوبة)","الخطأ في طرح الأسس عند قسمة 10²⁴ على 10²¹"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-10-18T03:32:48.482Z"}'::jsonb)
