('mcq', 5, 'أيّ العينات الآتية تحتوي على أكبر عدد من مولات ذرات الأكسجين؟', '{"headers":["العينة","الصيغة","كمية المركب"],"rows":[["1","H₂SO₄","2.0 mol"],["2","CO₂","3.0 mol"],["3","Al₂O₃","1.5 mol"],["4","Mg(OH)₂","2.5 mol"]]}'::jsonb, '["العينة 1 (H₂SO₄)","العينة 2 (CO₂)","العينة 3 (Al₂O₃)","العينة 4 (Mg(OH)₂)"]'::jsonb, 'تحليل', 'مقارنة بين عينات بالصيغة والمولات', 'صعب', 'الكتاب ص 169، 182 — علاقات المول المرتبطة بالصيغة (س112)'),
