from (values
('mcq', 1, 2, 'الرقم 3 خارج القوس يدل على أن كل مول من Al₂(SO₄)₃ يحتوي 3 mol من SO₄²⁻، فعامل التحويل هو (3 mol SO₄²⁻ / 1 mol Al₂(SO₄)₃). عدد المولات = 2.00 mol × 3 = 6.00 mol، وهو الخيار «6.00 mol».', '["هذا الناتج يفترض أن كل مول من المركب يعطي مولًا واحدًا من الكبريتات، متجاهلًا الرقم 3 خارج القوس.","هذا الناتج مأخوذ من الرقم السفلي للألومنيوم (2) بدلًا من الرقم الذي يلي القوس (3).","","هذا الناتج مأخوذ من عدد ذرات الأكسجين في الأيون الواحد (4 × 2.00)، وليس من عدد أيونات الكبريتات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-18T03:32:48.482Z"}'::jsonb),
('mcq', 2, 0, 'الرقم 22 يدل على أن كل مول من السكروز يحتوي 22 mol من ذرات H، فعامل التحويل (22 mol H / 1 mol C₁₂H₂₂O₁₁). 1.50 mol × 22 = 33.0 mol، وهو الخيار «33.0 mol».', '["","هذا الناتج هو عدد مولات ذرات الكربون (1.50 × 12) وليس الهيدروجين.","هذا العدد هو مولات H في مول واحد من السكروز؛ نسي الطالب الضرب في 1.50 mol.","هذا الناتج هو مولات الذرات الكلية (45 × 1.50)، وليس ذرات الهيدروجين وحدها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:32:48.482Z"}'::jsonb),
('mcq', 3, 3, 'الرقم السفلي 4 بعد O في الصيغة يدل على أن مولًا واحدًا من Na₃PO₄ يحتوي 4 mol من ذرات O، فيكون عامل التحويل (4 mol O / 1 mol Na₃PO₄) بحيث تُحذف مولات المركب ويبقى mol O.', '["هذا العامل مقلوب؛ يربط مولًا واحدًا من O بأربعة مولات من المركب، وهذا لا يطابق الصيغة.","الرقم 3 هو عدد مولات الصوديوم Na في مول المركب وليس مولات الأكسجين.","الرقم 8 ناتج جمع الأرقام السفلية (3 + 1 + 4)، وهو خطأ لأن كل رقم يخص عنصره فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-18T03:32:48.483Z"}'::jsonb),
('mcq', 4, 1, 'في Ca(NO₃)₂ يوجد أيونا نترات، وفي كل أيون 3 ذرات O؛ أي 2 × 3 = 6 mol O في كل مول من المركب. 3.00 mol × 6 = 18.0 mol، وهو الخيار «18.0 mol».', '["هذا الناتج يضرب الرقم 3 فقط (3.00 × 3) ويهمل الرقم 2 خارج القوس.","","هذا الناتج يضرب الرقم 2 خارج القوس فقط (3.00 × 2) ويهمل الرقم 3 داخل القوس.","هذا الناتج يجمع الرقمين (2 + 3 = 5) بدلًا من ضربهما، ثم يضرب في 3.00."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:32:48.483Z"}'::jsonb),
('mcq', 5, 0, 'مولات O = كمية المركب × عدد ذرات O في الصيغة: H₂SO₄ تعطي 2.0 × 4 = 8.0 mol؛ CO₂ تعطي 3.0 × 2 = 6.0 mol؛ Al₂O₃ تعطي 1.5 × 3 = 4.5 mol؛ Mg(OH)₂ تعطي 2.5 × 2 = 5.0 mol. أكبرها 8.0 mol في العينة 1، وهو الخيار «العينة 1 (H₂SO₄)».', '["","العينة 2 أكبر كمية مركب (3.0 mol) لكنها تحتوي 6.0 mol O فقط؛ فالمقارنة تكون بمولات الأكسجين لا بمولات المركب.","العينة 3 تحتوي 4.5 mol O، وهي أقل من 8.0 mol في العينة 1.","العينة 4 تحتوي 5.0 mol O، وهي أقل من 8.0 mol في العينة 1."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:32:48.483Z"}'::jsonb),
('mcq', 6, 2, 'كل مول من Na₂CO₃ يحتوي 2 mol من Na⁺، فعامل التحويل (1 mol Na₂CO₃ / 2 mol Na⁺). 0.90 mol Na⁺ × (1 / 2) = 0.45 mol Na₂CO₃، وهو الخيار «0.45 mol».', '["هذا الناتج ضرب في 2 بدلًا من القسمة؛ استعمل عامل التحويل مقلوبًا.","هذا الناتج يفترض نسبة 1 : 1 بين Na⁺ والمركب، ويتجاهل الرقم 2 في الصيغة.","","هذا الناتج قسم على 3، وهو عدد الأيونات الكلي في وحدة الصيغة (2 Na⁺ + 1 CO₃²⁻)، بدلًا من القسمة على عدد أيونات Na⁺ فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.483Z"}'::jsonb),
('mcq', 7, 1, 'في (NH₄)₂SO₄ يوجد أيونا أمونيوم NH₄⁺، وفي كل أيون 4 ذرات H؛ أي 2 × 4 = 8 mol H في كل مول من المركب. 4.00 mol × 8 = 32.0 mol، وهو الخيار «32.0 mol».', '["هذا الناتج يستعمل الرقم 2 خارج القوس فقط (4.00 × 2) ويهمل الرقم 4 بعد H.","","هذا الناتج يستعمل الرقم 4 بعد H فقط (4.00 × 4) ويهمل الرقم 2 خارج القوس.","هذا الناتج هو مولات الذرات الكلية (15 × 4.00) وليس ذرات الهيدروجين وحدها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-18T03:32:48.483Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الأرقام السفلية في CCl₂F₂ تدل على أن كل مول من المركب يحتوي 1 mol C و2 mol Cl و2 mol F. عوامل التحويل: (1 mol C / 1 mol CCl₂F₂)، (2 mol Cl / 1 mol CCl₂F₂)، (2 mol F / 1 mol CCl₂F₂). مولات C = 3.20 mol × 1 = 3.20 mol. مولات Cl = 3.20 mol × 2 = 6.40 mol. مولات F = 3.20 mol × 2 = 6.40 mol. المجموع = 3.20 + 6.40 + 6.40 = 16.0 mol من الذرات (أو 3.20 mol × 5).', '["عوامل التحويل الثلاثة مشتقة من الأرقام السفلية في الصيغة","3.20 mol C","6.40 mol Cl","6.40 mol F","مجموع مولات الذرات 16.0 mol"]'::jsonb, '["كل مول من CCl₂F₂ يحتوي 1 mol C و2 mol Cl و2 mol F","mol C = 3.20 mol CCl₂F₂ × (1 mol C / 1 mol CCl₂F₂) = 3.20 mol","mol Cl = 3.20 mol × (2 mol Cl / 1 mol CCl₂F₂) = 6.40 mol","mol F = 3.20 mol × (2 mol F / 1 mol CCl₂F₂) = 6.40 mol","المجموع = 3.20 + 6.40 + 6.40 = 16.0 mol"]'::jsonb, '[{"element":"كتابة عوامل التحويل الثلاثة صحيحة","marks":1},{"element":"mol C = 3.20 mol","marks":1},{"element":"mol Cl = 6.40 mol","marks":1},{"element":"mol F = 6.40 mol","marks":1},{"element":"المجموع 16.0 mol","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"عوامل التحويل صحيحة، والمولات الثلاثة صحيحة، والمجموع صحيح بوحداته"},{"level":"3–4 درجات","description":"عوامل التحويل أو أغلب الحسابات صحيحة مع خطأ واحد في عنصر أو في المجموع"},{"level":"1–2 درجة","description":"كتابة عامل تحويل صحيح أو حساب عنصر واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قلب عامل التحويل فتُقسم المولات بدل أن تُضرب","نسيان الرقم 2 المرافق لـ Cl وF أو عدّه ذرة واحدة","كتابة المجموع 3 × 3.20 = 9.60 mol بدلًا من جمع مولات الذرات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.483Z"}'::jsonb),
('essay', 2, null::int, null, null, 'في كل مول من Al₂(SO₄)₃ يوجد 2 mol Al³⁺ و3 mol SO₄²⁻ (الرقم 3 خارج القوس يضاعف كل ما بداخله). عدد مولات Al³⁺ = 0.250 mol × 2 = 0.500 mol. عدد مولات SO₄²⁻ = 0.250 mol × 3 = 0.750 mol. وفي كل أيون كبريتات 4 ذرات O، فعدد ذرات O في مول المركب = 3 × 4 = 12 mol، وعدد مولات O = 0.250 mol × 12 = 3.00 mol. الرقم خارج القوس يضرب في الأرقام داخله جميعها.', '["0.500 mol Al³⁺","0.750 mol SO₄²⁻","3.00 mol O","الرقم خارج القوس يضرب في أرقام ما داخله"]'::jsonb, '["كل مول Al₂(SO₄)₃ يحتوي 2 mol Al³⁺ و3 mol SO₄²⁻","mol Al³⁺ = 0.250 mol × (2 mol Al³⁺ / 1 mol Al₂(SO₄)₃) = 0.500 mol","mol SO₄²⁻ = 0.250 mol × (3 mol SO₄²⁻ / 1 mol Al₂(SO₄)₃) = 0.750 mol","mol O في مول المركب = 3 × 4 = 12 mol","mol O = 0.250 mol × (12 mol O / 1 mol Al₂(SO₄)₃) = 3.00 mol"]'::jsonb, '[{"element":"mol Al³⁺ = 0.500 mol","marks":1},{"element":"mol SO₄²⁻ = 0.750 mol","marks":1},{"element":"mol O = 3.00 mol مع ضرب 3 × 4","marks":1},{"element":"توضيح أن الرقم خارج القوس يضاعف ما بداخله","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحسابات الثلاثة صحيحة مع توضيح معنى الرقم خارج القوس"},{"level":"2–3 درجات","description":"حسابان صحيحان، أو الحسابات صحيحة دون توضيح"},{"level":"1 درجة","description":"حساب واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب mol O بالضرب في 4 فقط وإهمال الرقم 3 خارج القوس","عدّ Al³⁺ ثلاثة مولات بدل مولين لتأثر الطالب بالرقم 3 خارج القوس","ضرب الأعداد ببعضها (2 × 3 = 6) في كل خطوة بدل اختيار الرقم الخاص بكل أيون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-18T03:32:48.484Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الرقم السفلي بعد C يدل على عدد مولات الكربون في مول واحد من المركب: 6 mol في C₆H₈O₆، و3 mol في C₃H₈O₃، و8 mol في C₈H₈O₃؛ فأكبرها C₈H₈O₃ لأن عدد مولات الكربون فيه أكبر. (ب) mol C = 2.50 mol × 6 = 15.0 mol في حمض الأسكوربيك؛ 2.50 × 3 = 7.50 mol في الجلسرين؛ 2.50 × 8 = 20.0 mol في C₈H₈O₃.', '["الرقم السفلي بعد C يمثل عدد مولات الكربون في مول واحد","C₈H₈O₃ هو الأكبر (8 mol)","15.0 mol C في حمض الأسكوربيك","7.50 mol C في الجلسرين","20.0 mol C في C₈H₈O₃"]'::jsonb, '["مولات C في مول واحد: 6 و3 و8 على الترتيب","C₆H₈O₆: 2.50 mol × 6 = 15.0 mol C","C₃H₈O₃: 2.50 mol × 3 = 7.50 mol C","C₈H₈O₃: 2.50 mol × 8 = 20.0 mol C"]'::jsonb, '[{"element":"تحديد C₈H₈O₃ الأكبر","marks":1},{"element":"التفسير بعدد مولات C في مول واحد من الصيغة","marks":1},{"element":"15.0 mol C","marks":1},{"element":"7.50 mol C","marks":1},{"element":"20.0 mol C","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحديد المركب مع تفسير صحيح، والحسابات الثلاثة صحيحة بوحداتها"},{"level":"3–4 درجات","description":"التحديد والتفسير صحيحان مع خطأ في حساب أو أكثر، أو الحسابات صحيحة دون تفسير"},{"level":"1–2 درجة","description":"تحديد صحيح دون تفسير ودون حسابات، أو حساب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار المركب الأكثر ذرات كليًّا بدل الأكثر ذرات كربون","الخلط بين عدد ذرات H وعدد ذرات C لأن الرقم 8 يتكرر","نسيان الضرب في 2.50 mol والاكتفاء بالرقم السفلي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.484Z"}'::jsonb)
