from (values
('mcq', 1, 1, 'في CaCl₂ مول واحد من Ca ومولان من Cl، فالكتلة المولية = 1 × 40.08 + 2 × 35.45 = 40.08 + 70.90 = 110.98 g/mol، وهو الخيار «110.98 g/mol».', '["هذا الناتج (40.08 + 35.45) يعدّ ذرة كلور واحدة فقط ويهمل الرقم 2 في الصيغة.","","هذا الناتج (2 × 40.08 + 35.45) ضرب كتلة الكالسيوم في 2 بدل كتلة الكلور، أي عكس موضع الرقم السفلي.","هذا الناتج (2 × 35.45) هو كتلة مولي الكلور فقط، ولم تُضف إليه كتلة الكالسيوم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-10-18T03:32:48.484Z"}'::jsonb),
('mcq', 2, 3, 'الرقم 2 خارج القوس يضاعف ما بداخله: في Ca(NO₃)₂ يوجد 1 mol Ca و2 mol N و6 mol O. الكتلة المولية = 40.08 + 2 × 14.01 + 6 × 16.00 = 40.08 + 28.02 + 96.00 = 164.10 g/mol.', '["هذا الناتج (40.08 + 14.01 + 3 × 16.00 = 102.09) أهمل الرقم 2 خارج القوس تمامًا.","هذا الناتج (40.08 + 28.02 + 48.00 = 116.10) ضاعف كتلة N فقط ولم يضاعف كتلة O (3 ذرات بدل 6).","هذا الناتج (40.08 + 14.01 + 96.00 = 150.09) ضاعف كتلة O فقط ولم يضاعف كتلة N.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-10-18T03:32:48.485Z"}'::jsonb),
('mcq', 3, 0, 'في (NH₄)₃PO₄ يوجد 3 mol N و12 mol H (3 × 4) و1 mol P و4 mol O. الكتلة المولية = 3 × 14.01 + 12 × 1.008 + 30.97 + 4 × 16.00 = 42.03 + 12.096 + 30.97 + 64.00 = 149.096 ≈ 149.10 g/mol (بأقل عدد منازل عشرية هو منزلان).', '["","هذا الناتج (14.01 + 4.032 + 30.97 + 64.00 = 113.01) أهمل الرقم 3 خارج القوس فعدّ أيون أمونيوم واحدًا.","هذا الناتج (42.03 + 4.032 + 30.97 + 64.00 = 141.03) ضاعف كتلة N فقط ولم يضاعف كتلة H في الأقواس.","هذا الناتج (42.03 + 12.096 + 30.97 = 85.10) أهمل كتلة الأكسجين في أيون الفوسفات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-10-18T03:32:48.485Z"}'::jsonb),
('mcq', 4, 2, 'الكتلة المولية = 12 × 12.01 + 22 × 1.008 + 11 × 16.00 = 144.12 + 22.176 + 176.00 = 342.296 ≈ 342.30 g/mol، وهو الخيار «342.30 g/mol».', '["هذا الناتج (144.12 + 1.008 + 16.00) ضرب كتلة C فقط في الرقم السفلي وترك H وO دون ضرب.","هذا الناتج (144.12 + 176.00) أهمل كتلة الهيدروجين.","","هذا الناتج (12 + 22 + 11) جمع الأرقام السفلية في الصيغة دون استعمال الكتل المولية للعناصر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-10-18T03:32:48.485Z"}'::jsonb),
('mcq', 5, 3, 'في Mg(OH)₂ يوجد 1 mol Mg و2 mol O و2 mol H، فيجب ضرب كتلتي O وH في 2. الحساب الصحيح: 24.31 + 2 × 16.00 + 2 × 1.008 = 24.31 + 32.00 + 2.016 = 58.33 g/mol. الخطأ هو إهمال الرقم 2 الواقع خارج القوس.', '["الكتلة المولية للمركب مجموع كتل عناصره المضروبة في أعدادها، وليس حاصل ضرب الكتل بعضها في بعض.","لم يستعمل الطالب عدد أفوجادرو؛ استعمل الكتل المولية الصحيحة لكنه أهمل عدد المولات من كل عنصر.","الطالب جمع كتلة الهيدروجين ولم يطرحها؛ والخطأ هو إهمال الرقم 2.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-18T03:32:48.485Z"}'::jsonb),
('mcq', 6, 0, 'في KMnO₄ يوجد 1 mol K و1 mol Mn و4 mol O. الكتلة المولية = 39.10 + 54.94 + 4 × 16.00 = 39.10 + 54.94 + 64.00 = 158.04 g/mol.', '["","هذا الناتج (39.10 + 54.94 + 48.00) عدّ 3 ذرات أكسجين بدل 4.","هذا الناتج (78.20 + 54.94 + 64.00) ضاعف كتلة البوتاسيوم، وكأن الصيغة K₂MnO₄.","هذا الناتج (39.10 + 54.94) أهمل كتلة الأكسجين كلها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-18T03:32:48.485Z"}'::jsonb),
('mcq', 7, 2, 'الكتلة المولية = 1.008 + 14.01 + 3 × 16.00 = 1.008 + 14.01 + 48.00 = 63.018 g/mol. عند الجمع يُقرَّب الناتج إلى أقل عدد من المنازل العشرية بين الأعداد (منزلان في 14.01 و48.00) فيكون 63.02 g/mol.', '["هذا الناتج (1.008 + 14.01 + 16.00) عدّ ذرة أكسجين واحدة فقط ولم يضرب في الرقم 3.","هذا الناتج (14.01 + 48.00) أهمل كتلة الهيدروجين.","","هذا الناتج (1.008 + 14.01 + 32.00) عدّ ذرتي أكسجين بدل ثلاث."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-18T03:32:48.486Z"}'::jsonb),
('essay', 1, null::int, null, null, 'نحدد عدد مولات كل عنصر في مول واحد من Fe₂(SO₄)₃: 2 mol Fe، و3 mol S، و12 mol O (3 × 4). كتلة Fe = 2 × 55.85 = 111.70 g. كتلة S = 3 × 32.07 = 96.21 g. كتلة O = 12 × 16.00 = 192.00 g. الكتلة المولية = 111.70 + 96.21 + 192.00 = 399.91 g/mol.', '["أعداد المولات: 2 Fe و3 S و12 O","كتلة Fe = 111.70 g","كتلة S = 96.21 g","كتلة O = 192.00 g","الكتلة المولية = 399.91 g/mol"]'::jsonb, '["عدد مولات العناصر في مول المركب: Fe = 2، S = 3، O = 3 × 4 = 12","2 mol Fe × 55.85 g/mol = 111.70 g","3 mol S × 32.07 g/mol = 96.21 g","12 mol O × 16.00 g/mol = 192.00 g","المجموع: 111.70 + 96.21 + 192.00 = 399.91 g/mol"]'::jsonb, '[{"element":"تحديد أعداد المولات الصحيحة (2 و3 و12)","marks":1},{"element":"حساب كتل العناصر الثلاثة","marks":2},{"element":"الجمع والنتيجة 399.91 g/mol بوحدتها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"أعداد المولات صحيحة، والكتل الثلاث صحيحة، والناتج 399.91 g/mol بوحدته"},{"level":"2–3 درجات","description":"خطأ في عدد ذرات الأكسجين أو في إحدى الكتل مع سلامة المنهج"},{"level":"1 درجة","description":"ذكر المنهج أو حساب كتلة عنصر واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب ذرات الأكسجين 4 بدل 12 لإهمال الرقم 3 خارج القوس","كتابة الناتج بوحدة g بدل g/mol","تقريب الناتج إلى 400 g/mol أو 399.9 g/mol دون مراعاة المنازل العشرية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-18T03:32:48.486Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) Na₃PO₄: 3 × 22.99 = 68.97 g، و1 × 30.97 = 30.97 g، و4 × 16.00 = 64.00 g؛ المجموع = 163.94 g/mol. (ب) C₂H₅OH: عدد ذرات H = 5 + 1 = 6، فالصيغة C₂H₆O: 2 × 12.01 = 24.02 g، و6 × 1.008 = 6.048 g، و1 × 16.00 = 16.00 g؛ المجموع = 46.068 ≈ 46.07 g/mol.', '["Na₃PO₄: 68.97 + 30.97 + 64.00","163.94 g/mol","C₂H₅OH يحتوي 6 ذرات H (5 + 1)","24.02 + 6.048 + 16.00","46.07 g/mol"]'::jsonb, '["Na₃PO₄: 3 × 22.99 + 30.97 + 4 × 16.00 = 68.97 + 30.97 + 64.00 = 163.94 g/mol","C₂H₅OH: عدد ذرات H = 6، O = 1، C = 2","2 × 12.01 + 6 × 1.008 + 16.00 = 24.02 + 6.048 + 16.00 = 46.068","التقريب إلى منزلين عشريين: 46.07 g/mol"]'::jsonb, '[{"element":"حساب Na₃PO₄ = 163.94 g/mol","marks":2},{"element":"عدّ ذرات H في C₂H₅OH ست ذرات","marks":1},{"element":"حساب C₂H₅OH = 46.07 g/mol","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الكتلتان المولّيتان صحيحتان بوحدتيهما مع عدّ صحيح لذرات الهيدروجين"},{"level":"2–3 درجات","description":"إحدى الكتلتين صحيحة، أو خطأ في عدّ H مع سلامة المنهج"},{"level":"1 درجة","description":"حساب كتلة عنصر واحد أو ذكر المنهج فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ ذرات الهيدروجين في C₂H₅OH خمسًا فقط وإهمال هيدروجين مجموعة OH","ضرب كتلة الأكسجين في 3 بدل 4 في Na₃PO₄","الجمع دون ضرب الكتل في عدد المولات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-18T03:32:48.486Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الخطأ: لم يضرب كتلتي O وH في العدد 3 الواقع خارج القوس؛ فالصيغة تدل على 1 mol Al و3 mol O و3 mol H في مول واحد من المركب، فالكتلة المولية مجموع كتل جميع المولات من العناصر. الحساب الصحيح: Al: 1 × 26.98 = 26.98 g؛ O: 3 × 16.00 = 48.00 g؛ H: 3 × 1.008 = 3.024 g؛ المجموع = 26.98 + 48.00 + 3.024 = 78.004 ≈ 78.00 g/mol.', '["الخطأ إهمال العدد 3 خارج القوس","الصيغة تدل على 3 mol O و3 mol H في مول المركب","26.98 + 48.00 + 3.024","78.00 g/mol"]'::jsonb, '["في مول Al(OH)₃: 1 mol Al و3 mol O و3 mol H","Al: 1 × 26.98 = 26.98 g","O: 3 × 16.00 = 48.00 g","H: 3 × 1.008 = 3.024 g","المجموع = 78.004 ≈ 78.00 g/mol"]'::jsonb, '[{"element":"تحديد الخطأ: إهمال العدد 3 خارج القوس","marks":1},{"element":"تفسير الخطأ بعدد مولات O وH في مول المركب","marks":1},{"element":"حساب كتل العناصر الثلاثة صحيحًا","marks":1},{"element":"الناتج 78.00 g/mol","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد الخطأ وتفسيره وحساب الكتلة المولية الصحيحة بوحدتها"},{"level":"2–3 درجات","description":"تحديد الخطأ مع خطأ في التفسير أو في الحساب"},{"level":"1 درجة","description":"تحديد الخطأ دون تفسير أو حساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الخطأ في كتلة الهيدروجين لا في العدد 3","ضرب العدد 3 في كتلة Al أيضًا","كتابة الناتج 78.004 دون تقريب إلى منزلين عشريين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-18T03:32:48.486Z"}'::jsonb)
