from (values
('mcq', 1, 'كم وحدة صيغة في عينة من كلوريد الصوديوم NaCl كتلتها 11.7 g؟ (الكتلة المولية لـ NaCl = 58.44 g/mol، وعدد أفوجادرو 6.02 × 10²³)', null, '["0.200 وحدة صيغة","1.21 × 10²³ وحدة صيغة","2.41 × 10²³ وحدة صيغة","4.12 × 10²⁶ وحدة صيغة"]'::jsonb, 'تطبيق', 'تحويل كتلة مركب إلى عدد وحدات صيغة', 'سهل', 'الكتاب ص 173–174 — تحويل كتلة مركب إلى عدد جسيمات (مثال 5-9)'),
('mcq', 2, 'كم أيون كلوريد Cl⁻ في عينة من كلوريد الكالسيوم CaCl₂ كتلتها 22.2 g؟ (الكتلة المولية لـ CaCl₂ = 110.98 g/mol، وعدد أفوجادرو 6.02 × 10²³)', null, '["2.41 × 10²³ أيون","1.20 × 10²³ أيون","3.61 × 10²³ أيون","6.02 × 10²⁴ أيون"]'::jsonb, 'تطبيق', 'حساب عدد أيونات من كتلة المركب', 'متوسط', 'الكتاب ص 173–174 — تحويل كتلة مركب إلى عدد جسيمات (مثال 5-9)'),
('mcq', 3, 'كم ذرة هيدروجين في عينة من الإيثانول C₂H₅OH كتلتها 23.0 g؟ (الكتلة المولية لـ C₂H₅OH = 46.07 g/mol، وعدد أفوجادرو 6.02 × 10²³)', null, '["3.01 × 10²³ ذرة","1.50 × 10²⁴ ذرة","2.71 × 10²⁴ ذرة","1.80 × 10²⁴ ذرة"]'::jsonb, 'تطبيق', 'حساب عدد ذرات عنصر في كتلة من مركب جزيئي', 'صعب', 'الكتاب ص 174 — تحويل كتلة مركب إلى عدد جسيمات (س42)'),
('mcq', 4, 'ما كتلة وحدة صيغة واحدة من NaCl بالجرامات؟ (الكتلة المولية لـ NaCl = 58.44 g/mol، وعدد أفوجادرو 6.02 × 10²³)', null, '["1.03 × 10²² g","1.66 × 10⁻²⁴ g","9.71 × 10⁻²³ g","3.52 × 10²⁵ g"]'::jsonb, 'تطبيق', 'حساب كتلة وحدة صيغة', 'متوسط', 'الكتاب ص 174 — تحويل كتلة مركب إلى عدد جسيمات (مثال 5-9، الفقرة c)'),
('mcq', 5, 'أُخذت عينة كتلتها 10.0 g من كل مادة من المواد الآتية. أيّ العينات تحتوي أكبر عدد من الجسيمات الممثلة (جزيئات أو وحدات صيغة)؟', '{"headers":["المادة","نوع الجسيم الممثل","الكتلة المولية (g/mol)"],"rows":[["H₂O","جزيء","18.02"],["NaCl","وحدة صيغة","58.44"],["CO₂","جزيء","44.01"],["CH₄","جزيء","16.04"]]}'::jsonb, '["عينة H₂O","عينة NaCl","عينة CO₂","عينة CH₄"]'::jsonb, 'تحليل', 'مقارنة أعداد الجسيمات لكتل متساوية', 'متوسط', 'الكتاب ص 173 — تحويل كتلة مركب إلى عدد جسيمات'),
('mcq', 6, 'أيّ سلسلة عوامل تحويل صحيحة لإيجاد عدد أيونات Cl⁻ في كتلة معلومة بالجرامات من AlCl₃ (الكتلة المولية 133.33 g/mol)؟', null, '["الكتلة × (133.33 g / 1 mol) × (6.02 × 10²³ وحدة صيغة / 1 mol) × (3 Cl⁻ / 1 وحدة صيغة)","الكتلة × (1 mol / 133.33 g) × (6.02 × 10²³ وحدة صيغة / 1 mol) × (3 Cl⁻ / 1 وحدة صيغة)","الكتلة × (1 mol / 133.33 g) × (3 Cl⁻ / 1 وحدة صيغة)","الكتلة × (1 mol / 133.33 g) × (1 mol / 6.02 × 10²³ وحدة صيغة) × (3 Cl⁻ / 1 وحدة صيغة)"]'::jsonb, 'فهم', 'اختيار سلسلة عوامل التحويل الصحيحة', 'سهل', 'الكتاب ص 173–175 — تحويل كتلة مركب إلى عدد جسيمات'),
('mcq', 7, 'ما العدد الكلي للأيونات (Na⁺ و SO₄²⁻) في عينة من كبريتات الصوديوم Na₂SO₄ كتلتها 14.2 g؟ (الكتلة المولية لـ Na₂SO₄ = 142.05 g/mol، وعدد أفوجادرو 6.02 × 10²³)', null, '["1.81 × 10²³ أيون","6.02 × 10²² أيون","1.20 × 10²³ أيون","4.21 × 10²³ أيون"]'::jsonb, 'تطبيق', 'حساب العدد الكلي للأيونات', 'صعب', 'الكتاب ص 173–174 — تحويل كتلة مركب إلى عدد جسيمات (مثال 5-9)'),
('essay', 1, 'عينة من ثاني أكسيد الكربون CO₂ كتلتها 11.0 g. احسب: (أ) عدد جزيئات CO₂ في العينة، (ب) عدد ذرات الكربون، (ج) عدد ذرات الأكسجين، (د) كتلة جزيء واحد من CO₂ بالجرامات. (الكتلة المولية لـ CO₂ = 44.01 g/mol، وعدد أفوجادرو 6.02 × 10²³)', null, null, 'تطبيق', 'حل مسألة متعددة الخطوات على مركب جزيئي', 'سهل', 'الكتاب ص 174، 182 — تحويل كتلة مركب إلى عدد جسيمات (س44، س121)'),
('essay', 2, 'عينة من نترات الكالسيوم Ca(NO₃)₂ كتلتها 45.0 g. احسب: (أ) عدد وحدات الصيغة، (ب) عدد أيونات Ca²⁺، (ج) عدد أيونات NO₃⁻، (د) عدد ذرات الأكسجين في العينة. (الكتلة المولية لـ Ca(NO₃)₂ = 164.10 g/mol، وعدد أفوجادرو 6.02 × 10²³)', null, null, 'تطبيق', 'حل مسألة متعددة الخطوات على مركب أيوني فيه قوس', 'متوسط', 'الكتاب ص 173–174 — تحويل كتلة مركب إلى عدد جسيمات (مثال 5-9)'),
('essay', 3, 'عينتان كتلة كل منهما 10.0 g: الأولى من كلوريد الصوديوم NaCl والثانية من كلوريد الكالسيوم CaCl₂. أيّ العينتين تحتوي عددًا أكبر من الأيونات الكلية؟ أثبت إجابتك بحساب عدد الأيونات في كل عينة. (الكتلة المولية: NaCl = 58.44 g/mol، CaCl₂ = 110.98 g/mol، وعدد أفوجادرو 6.02 × 10²³)', null, null, 'تحليل', 'مقارنة بحساب كمي واستنتاج', 'صعب', 'الكتاب ص 173–174 — تحويل كتلة مركب إلى عدد جسيمات (مثال 5-9)')
