from (values
('mcq', 1, 1, 'نحوّل الكتلة إلى مولات: 11.7 g × (1 mol / 58.44 g) = 0.200 mol، ثم إلى وحدات صيغة: 0.200 mol × 6.02 × 10²³ = 1.21 × 10²³ وحدة صيغة، وهو الخيار «1.21 × 10²³ وحدة صيغة».', '["هذا العدد هو عدد المولات؛ توقف الطالب قبل الضرب في عدد أفوجادرو.","","هذا الناتج هو عدد الأيونات الكلي (2 × 1.21 × 10²³) وليس عدد وحدات الصيغة.","هذا الناتج ضرب الكتلة في الكتلة المولية (11.7 × 58.44) بدل القسمة، ثم في عدد أفوجادرو."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (59%)"}],"at":"2026-10-18T03:32:48.488Z"}'::jsonb),
('mcq', 2, 0, 'مولات CaCl₂ = 22.2 g × (1 mol / 110.98 g) = 0.200 mol، وعدد وحدات الصيغة = 0.200 × 6.02 × 10²³ = 1.20 × 10²³. كل وحدة صيغة فيها أيونا Cl⁻، فعدد Cl⁻ = 1.20 × 10²³ × 2 = 2.41 × 10²³ أيون.', '["","هذا العدد هو عدد وحدات الصيغة، ولم يُضرب في 2 لأن كل وحدة صيغة تحتوي أيوني كلوريد.","هذا العدد هو عدد الأيونات الكلي (Ca²⁺ و Cl⁻ معًا: 3 أيونات لكل وحدة صيغة) وليس أيونات الكلوريد وحدها.","هذا الناتج استعمل مقلوب الكتلة المولية (110.98 / 22.2) بدل (22.2 / 110.98)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-10-18T03:32:48.488Z"}'::jsonb),
('mcq', 3, 3, 'مولات الإيثانول = 23.0 g × (1 mol / 46.07 g) = 0.499 mol، وعدد الجزيئات = 0.499 × 6.02 × 10²³ = 3.01 × 10²³ جزيء. كل جزيء C₂H₅OH يحتوي 6 ذرات H (5 + 1)، فعدد ذرات H = 3.01 × 10²³ × 6 = 1.80 × 10²⁴ ذرة.', '["هذا العدد هو عدد الجزيئات، ولم يُضرب في عدد ذرات الهيدروجين في الجزيء.","هذا الناتج ضرب في 5 فقط، وأهمل ذرة الهيدروجين في مجموعة OH.","هذا الناتج ضرب في 9، وهو عدد الذرات الكلي في الجزيء (2 + 6 + 1) وليس ذرات الهيدروجين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-10-18T03:32:48.488Z"}'::jsonb),
('mcq', 4, 2, 'كتلة مول واحد 58.44 g تحتوي 6.02 × 10²³ وحدة صيغة، فكتلة وحدة الصيغة الواحدة = 58.44 g ÷ 6.02 × 10²³ = 9.71 × 10⁻²³ g.', '["هذا الناتج قسم عدد أفوجادرو على الكتلة المولية (6.02 × 10²³ / 58.44) بدل العكس.","هذا الناتج هو مقلوب عدد أفوجادرو (1 / 6.02 × 10²³) دون ضربه في الكتلة المولية.","","هذا الناتج ضرب الكتلة المولية في عدد أفوجادرو بدل القسمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (59%)"}],"at":"2026-10-18T03:32:48.488Z"}'::jsonb),
('mcq', 5, 3, 'عدد الجسيمات = (الكتلة ÷ الكتلة المولية) × 6.02 × 10²³؛ فعند تساوي الكتل تزداد الجسيمات كلما قلّت الكتلة المولية. CH₄ كتلته المولية الأصغر (16.04 g/mol) فعدد جزيئاته 3.75 × 10²³، وهو أكبر من H₂O (3.34 × 10²³) وCO₂ (1.37 × 10²³) وNaCl (1.03 × 10²³). الإجابة «عينة CH₄».', '["H₂O تحتوي 3.34 × 10²³ جزيء، وهي أقل من CH₄ لأن كتلتها المولية أكبر.","NaCl كتلتها المولية الأكبر (58.44 g/mol)، فتحتوي أقل عدد من وحدات الصيغة (1.03 × 10²³) لا أكبرها.","CO₂ تحتوي 1.37 × 10²³ جزيء فقط؛ كتلتها المولية (44.01 g/mol) كبيرة نسبيًّا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.489Z"}'::jsonb),
('mcq', 6, 1, 'لا يمكن التحويل مباشرة من الكتلة إلى الجسيمات. نضرب الكتلة في مقلوب الكتلة المولية (1 mol / 133.33 g) لنحصل على المولات، ثم في عدد أفوجادرو (6.02 × 10²³ وحدة صيغة / 1 mol) لنحصل على وحدات الصيغة، ثم في (3 Cl⁻ / 1 وحدة صيغة) لنحصل على الأيونات. وهذه السلسلة.', '["استعمل الكتلة المولية بدل مقلوبها، فلا تُحذف وحدة g ولا تظهر المولات.","","حذف خطوة عدد أفوجادرو؛ فالناتج يبقى بالمولات ولا يصل إلى عدد الأيونات.","استعمل مقلوب عدد أفوجادرو (1 mol / 6.02 × 10²³)، فلا تُحذف وحدة mol ولا يظهر عدد وحدات الصيغة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.489Z"}'::jsonb),
('mcq', 7, 0, 'مولات Na₂SO₄ = 14.2 g × (1 mol / 142.05 g) = 0.100 mol، وعدد وحدات الصيغة = 0.100 × 6.02 × 10²³ = 6.02 × 10²². كل وحدة صيغة تعطي 3 أيونات (2 Na⁺ + 1 SO₄²⁻)، فالعدد الكلي = 6.02 × 10²² × 3 = 1.81 × 10²³ أيون.', '["","هذا العدد هو عدد وحدات الصيغة، ولم يُضرب في عدد الأيونات (3) لكل وحدة صيغة.","هذا العدد هو أيونات Na⁺ وحدها (2 × 6.02 × 10²²)، ولم تُحسب أيونات SO₄²⁻.","هذا الناتج عدّ الذرات الكلية (7 ذرات في الوحدة) بدل الأيونات (3 أيونات)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-18T03:32:48.489Z"}'::jsonb),
('essay', 1, null::int, null, null, 'مولات CO₂ = 11.0 g × (1 mol / 44.01 g) = 0.250 mol. (أ) عدد الجزيئات = 0.250 mol × 6.02 × 10²³ = 1.50 × 10²³ جزيء. (ب) كل جزيء يحتوي ذرة C واحدة، فعدد ذرات C = 1.50 × 10²³. (ج) كل جزيء يحتوي ذرتي O، فعدد ذرات O = 1.50 × 10²³ × 2 = 3.01 × 10²³. (د) كتلة الجزيء = 44.01 g / 6.02 × 10²³ = 7.31 × 10⁻²³ g.', '["0.250 mol","1.50 × 10²³ جزيء","1.50 × 10²³ ذرة C","3.01 × 10²³ ذرة O","7.31 × 10⁻²³ g لكل جزيء"]'::jsonb, '["mol CO₂ = 11.0 g × (1 mol / 44.01 g) = 0.250 mol","الجزيئات = 0.250 mol × (6.02 × 10²³ جزيء / 1 mol) = 1.50 × 10²³","ذرات C = 1.50 × 10²³ جزيء × (1 C / 1 جزيء) = 1.50 × 10²³","ذرات O = 1.50 × 10²³ جزيء × (2 O / 1 جزيء) = 3.01 × 10²³","كتلة الجزيء = 44.01 g / 6.02 × 10²³ = 7.31 × 10⁻²³ g"]'::jsonb, '[{"element":"تحويل الكتلة إلى مولات (0.250 mol)","marks":1},{"element":"عدد الجزيئات 1.50 × 10²³","marks":1},{"element":"عدد ذرات C","marks":1},{"element":"عدد ذرات O","marks":1},{"element":"كتلة الجزيء الواحد","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الخطوات الخمس صحيحة بنتائجها ووحداتها"},{"level":"3–4 درجات","description":"تحويل صحيح إلى المولات والجزيئات مع خطأ في خطوة أو خطوتين لاحقتين"},{"level":"1–2 درجة","description":"حساب المولات فقط أو خطوة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الضرب في عدد أفوجادرو مباشرة من الكتلة دون التحويل إلى مولات","عدّ ذرات الأكسجين بعدد الجزيئات نفسه (ذرة واحدة)","ضرب الكتلة المولية في عدد أفوجادرو لإيجاد كتلة الجزيء بدل قسمتها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-10-18T03:32:48.489Z"}'::jsonb),
('essay', 2, null::int, null, null, 'مولات Ca(NO₃)₂ = 45.0 g × (1 mol / 164.10 g) = 0.274 mol. (أ) وحدات الصيغة = 0.274 mol × 6.02 × 10²³ = 1.65 × 10²³. (ب) كل وحدة تحتوي أيون Ca²⁺ واحدًا، فعدد Ca²⁺ = 1.65 × 10²³. (ج) كل وحدة تحتوي أيوني نترات، فعدد NO₃⁻ = 1.65 × 10²³ × 2 = 3.30 × 10²³. (د) كل أيون نترات فيه 3 ذرات O، فعدد ذرات O = 3.30 × 10²³ × 3 = 9.90 × 10²³ (أي 6 ذرات لكل وحدة صيغة).', '["0.274 mol","1.65 × 10²³ وحدة صيغة","1.65 × 10²³ أيون Ca²⁺","3.30 × 10²³ أيون NO₃⁻","9.90 × 10²³ ذرة O"]'::jsonb, '["mol = 45.0 g × (1 mol / 164.10 g) = 0.274 mol","وحدات الصيغة = 0.274 mol × 6.02 × 10²³ = 1.65 × 10²³","Ca²⁺ = 1.65 × 10²³ × 1 = 1.65 × 10²³","NO₃⁻ = 1.65 × 10²³ × 2 = 3.30 × 10²³","ذرات O = 3.30 × 10²³ × 3 = 9.90 × 10²³ (أو 1.65 × 10²³ × 6)"]'::jsonb, '[{"element":"المولات 0.274 mol","marks":1},{"element":"وحدات الصيغة 1.65 × 10²³","marks":1},{"element":"Ca²⁺ = 1.65 × 10²³","marks":1},{"element":"NO₃⁻ = 3.30 × 10²³","marks":1},{"element":"ذرات O = 9.90 × 10²³","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الخطوات الخمس صحيحة بنتائجها ووحداتها"},{"level":"3–4 درجات","description":"المولات ووحدات الصيغة صحيحة مع خطأ في إحدى نسب الأيونات أو الذرات"},{"level":"1–2 درجة","description":"حساب المولات أو وحدات الصيغة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال الرقم 2 خارج القوس فيُعدّ أيون نترات واحد لكل وحدة صيغة","عدّ ذرات الأكسجين 3 لكل وحدة صيغة بدل 6","استعمال كتلة Ca وحدها (40.08 g/mol) بدل الكتلة المولية للمركب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-10-18T03:32:48.490Z"}'::jsonb),
('essay', 3, null::int, null, null, 'عينة NaCl: mol = 10.0 / 58.44 = 0.171 mol؛ وحدات الصيغة = 0.171 × 6.02 × 10²³ = 1.03 × 10²³؛ كل وحدة تعطي أيونين (Na⁺ و Cl⁻)، فالأيونات = 2.06 × 10²³. عينة CaCl₂: mol = 10.0 / 110.98 = 0.0901 mol؛ وحدات الصيغة = 0.0901 × 6.02 × 10²³ = 5.42 × 10²²؛ كل وحدة تعطي 3 أيونات (Ca²⁺ و 2 Cl⁻)، فالأيونات = 1.63 × 10²³. إذن عينة NaCl أكبر؛ لأن كتلتها المولية أقل فعدد وحدات الصيغة فيها أكبر بما يفوق أثر وجود 3 أيونات بدل 2 في CaCl₂.', '["0.171 mol NaCl و1.03 × 10²³ وحدة صيغة","2.06 × 10²³ أيون في NaCl","0.0901 mol CaCl₂ و5.42 × 10²² وحدة صيغة","1.63 × 10²³ أيون في CaCl₂","عينة NaCl أكبر مع التعليل بالكتلة المولية"]'::jsonb, '["NaCl: 10.0 g × (1 mol / 58.44 g) = 0.171 mol","0.171 mol × 6.02 × 10²³ = 1.03 × 10²³ وحدة صيغة، × 2 أيون = 2.06 × 10²³ أيون","CaCl₂: 10.0 g × (1 mol / 110.98 g) = 0.0901 mol","0.0901 mol × 6.02 × 10²³ = 5.42 × 10²² وحدة صيغة، × 3 أيونات = 1.63 × 10²³ أيون","المقارنة: 2.06 × 10²³ أكبر من 1.63 × 10²³، فعينة NaCl أكبر"]'::jsonb, '[{"element":"حساب أيونات NaCl بخطواته (2.06 × 10²³)","marks":2},{"element":"حساب أيونات CaCl₂ بخطواته (1.63 × 10²³)","marks":2},{"element":"الاستنتاج مع تعليل بالكتلة المولية وعدد الأيونات","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حساب العينتين صحيح، واستنتاج صحيح مع تعليل"},{"level":"3–4 درجات","description":"حساب إحدى العينتين صحيحًا مع خطأ بسيط في الأخرى، أو حساب صحيح دون تعليل"},{"level":"1–2 درجة","description":"حساب المولات أو وحدات الصيغة في العينتين دون حساب الأيونات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الحكم بأن CaCl₂ أكبر لأن كل وحدة صيغة تعطي 3 أيونات دون حساب عدد وحدات الصيغة","عدّ أيونات NaCl أيونًا واحدًا لكل وحدة صيغة","مقارنة المولات فقط دون الانتقال إلى عدد الأيونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-18T03:32:48.490Z"}'::jsonb)
