from (values
('mcq', 1, 0, 'الكتلة المولية لـ H₂SO₄ = 2 × 1.008 + 32.07 + 4 × 16.00 = 98.09 g/mol. الكتلة = 2.50 mol × (98.09 g / 1 mol) = 245 g.', '["","هذا الناتج قسم الكتلة المولية على عدد المولات (98.09 / 2.50) بدل ضربها.","هذه هي كتلة مول واحد فقط؛ لم تُضرب الكتلة المولية في 2.50 mol.","هذا الناتج ضرب عدد المولات في مقلوب الكتلة المولية (2.50 / 98.09)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-18T03:32:48.491Z"}'::jsonb),
('mcq', 2, 2, 'الكتلة المولية لـ NaOH = 22.99 + 16.00 + 1.008 = 40.00 g/mol. عدد المولات = 50.0 g × (1 mol / 40.00 g) = 1.25 mol، وهو الخيار «1.25 mol».', '["هذا الناتج قسم الكتلة المولية على الكتلة (40.00 / 50.0) أي استعمل عامل التحويل مقلوبًا.","هذا الناتج ضرب الكتلة في الكتلة المولية (50.0 × 40.00) بدل القسمة.","","هذا الناتج استعمل كتلة الصوديوم وحدها (50.0 / 22.99) بدل الكتلة المولية لـ NaOH."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-10-18T03:32:48.491Z"}'::jsonb),
('mcq', 3, 1, 'لتحويل الجرامات إلى مولات يوضع المول في البسط والكتلة المولية في المقام لتُحذف وحدة g؛ فالعامل هو (1 mol Ca(OH)₂ / 74.10 g Ca(OH)₂).', '["هذا العامل يحوّل المولات إلى جرامات؛ استعمل الكتلة المولية دون قلبها، فلا تُحذف وحدة g.","","الرقم 40.08 g هو الكتلة المولية للكالسيوم وحده لا للمركب كله.","كتلة 74.10 g تقابل مولًا واحدًا من المركب لا مولين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:32:48.491Z"}'::jsonb),
('mcq', 4, 3, 'الكتلة = 0.250 mol × (180.16 g / 1 mol) = 45.04 g ≈ 45.0 g.', '["هذا الناتج قسم الكتلة المولية على عدد المولات (180.16 / 0.250) بدل الضرب.","هذه كتلة مول واحد من الجلوكوز؛ لم تُضرب في 0.250 mol.","هذا الناتج ضرب عدد المولات في مقلوب الكتلة المولية (0.250 / 180.16).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-18T03:32:48.491Z"}'::jsonb),
('mcq', 5, 0, 'الكتلة المولية لـ CaCO₃ = 40.08 + 12.01 + 3 × 16.00 = 100.09 g/mol. نحوّل الكتلة إلى جرامات: 1.50 kg = 1.50 × 10³ g، ثم 1.50 × 10³ g × (1 mol / 100.09 g) = 15.0 mol.', '["","هذا الناتج عدّ الكتلة 1.50 kg على أنها 1.50 g (1.50 / 100.09)؛ نسي تحويل kg إلى g.","هذا الناتج استعمل كتلة الكالسيوم وحدها (1500 / 40.08) بدل الكتلة المولية للمركب.","هذا الناتج ضرب الكتلة بالجرامات في الكتلة المولية (1500 × 100.09) بدل القسمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-10-18T03:32:48.491Z"}'::jsonb),
('mcq', 6, 2, 'الكتلة المولية لـ Na₂CO₃ = 2 × 22.99 + 12.01 + 3 × 16.00 = 105.99 g/mol. نحوّل الكتلة: 212 mg = 0.212 g، ثم 0.212 g × (1 mol / 105.99 g) = 2.00 × 10⁻³ mol.', '["هذا الناتج (212 / 105.99) عدّ mg على أنها g؛ نسي تحويل mg إلى g.","هذا الناتج حوّل mg إلى g بالضرب في 1000 بدل القسمة، فعكس اتجاه التحويل.","","هذا الناتج ضرب الكتلة بالجرامات في الكتلة المولية (0.212 × 105.99) بدل القسمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-10-18T03:32:48.492Z"}'::jsonb),
('mcq', 7, 1, 'الكتلة = عدد المولات × الكتلة المولية: CaCO₃ = 0.500 × 100.09 = 50.0 g؛ NaCl = 1.00 × 58.44 = 58.4 g؛ H₂O = 2.00 × 18.02 = 36.0 g؛ Fe₂O₃ = 0.250 × 159.70 = 39.9 g. أكبرها كتلة NaCl (58.4 g)، وهو الخيار «العينة 2 (NaCl)».', '["كتلة CaCO₃ = 50.0 g، وهي أقل من 58.4 g لـ NaCl رغم كبر كتلته المولية؛ لأن كميته 0.500 mol فقط.","","H₂O أكبر عدد مولات (2.00 mol) لكن كتلتها المولية صغيرة، فكتلتها 36.0 g فقط.","Fe₂O₃ أكبر كتلة مولية لكن كميتها 0.250 mol فقط، فكتلتها 39.9 g."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-18T03:32:48.492Z"}'::jsonb),
('essay', 1, null::int, null, null, 'نحسب الكتلة المولية: في (NH₄)₂CO₃ يوجد 2 mol N و8 mol H و1 mol C و3 mol O. 2 × 14.01 = 28.02 g؛ 8 × 1.008 = 8.064 g؛ 1 × 12.01 = 12.01 g؛ 3 × 16.00 = 48.00 g. المجموع = 96.09 g/mol. ثم الكتلة = 1.75 mol × (96.09 g / 1 mol) = 168 g.', '["عدد مولات العناصر: 2 N و8 H و1 C و3 O","الكتلة المولية 96.09 g/mol","استعمال عامل التحويل (96.09 g / 1 mol)","الكتلة 168 g"]'::jsonb, '["في مول المركب: 2 mol N، 8 mol H (2 × 4)، 1 mol C، 3 mol O","الكتلة المولية = 28.02 + 8.064 + 12.01 + 48.00 = 96.09 g/mol","الكتلة = 1.75 mol × (96.09 g / 1 mol) = 168.16 g","التقريب إلى ثلاثة أرقام معنوية: 168 g"]'::jsonb, '[{"element":"عدّ ذرات الهيدروجين 8 والنيتروجين 2","marks":1},{"element":"الكتلة المولية 96.09 g/mol","marks":1},{"element":"استعمال عامل التحويل الصحيح","marks":1},{"element":"الكتلة 168 g بوحدتها وأرقام معنوية صحيحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"عدّ صحيح، وكتلة مولية صحيحة، وتحويل صحيح، وناتج 168 g"},{"level":"2–3 درجات","description":"خطأ في الكتلة المولية مع سلامة خطوة التحويل، أو العكس"},{"level":"1 درجة","description":"ذكر المنهج أو حساب جزء من الكتلة المولية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ ذرات H أربعًا بإهمال الرقم 2 خارج القوس","قسمة المولات على الكتلة المولية بدل ضربها","كتابة الناتج 168.16 g بما يزيد على الأرقام المعنوية المعطاة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-18T03:32:48.492Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الكتلة المولية لـ Mg(OH)₂ = 24.31 + 2 × 16.00 + 2 × 1.008 = 24.31 + 32.00 + 2.016 = 58.33 g/mol. عدد المولات = 87.5 g × (1 mol / 58.33 g) = 1.50 mol. التحقق: نقرب الكتلة المولية إلى 60 g/mol والكتلة إلى 90 g، فيكون الناتج التقريبي 90 / 60 = 1.5 mol، وهو قريب من الناتج المحسوب، والوحدة (mol) صحيحة، فالإجابة معقولة.', '["الكتلة المولية 58.33 g/mol","استعمال مقلوب الكتلة المولية (1 mol / 58.33 g)","1.50 mol","التحقق بتقريب الأعداد وتوافقه مع الناتج"]'::jsonb, '["الكتلة المولية = 24.31 + 32.00 + 2.016 = 58.33 g/mol","mol = 87.5 g × (1 mol / 58.33 g) = 1.50 mol","التقريب: 90 g ÷ 60 g/mol = 1.5 mol","الناتج المحسوب قريب من التقريبي والوحدة صحيحة"]'::jsonb, '[{"element":"الكتلة المولية 58.33 g/mol","marks":1},{"element":"استعمال عامل التحويل بقلب الكتلة المولية","marks":1},{"element":"الناتج 1.50 mol","marks":1},{"element":"التحقق بالتقريب مع الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"كتلة مولية صحيحة، وتحويل صحيح، وناتج 1.50 mol، وتحقق بالتقريب"},{"level":"2–3 درجات","description":"حساب صحيح دون تحقق، أو تحقق صحيح مع خطأ بسيط في الحساب"},{"level":"1 درجة","description":"حساب الكتلة المولية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب الكتلة في الكتلة المولية بدل القسمة","إهمال الرقم 2 في (OH)₂ عند حساب الكتلة المولية","الاكتفاء بالتقريب دون الحساب الدقيق أو العكس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-18T03:32:48.492Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الكتلة المولية لـ CuSO₄ = 63.55 + 32.07 + 4 × 16.00 = 159.62 g/mol. (أ) الكتلة = 0.0500 mol × (159.62 g / 1 mol) = 7.98 g. (ب) عدد المولات في 12.5 g = 12.5 g × (1 mol / 159.62 g) = 0.0783 mol. (ج) 12.5 g أكبر من 7.98 g، فالمولات 0.0783 mol أكبر من 0.0500 mol المطلوبة. الحسابان متسقان؛ فالكتلة الأكبر تقابل مولات أكثر، ونسبة الكتلتين (12.5 / 7.98 = 1.57) تساوي نسبة المولات (0.0783 / 0.0500 = 1.57).', '["الكتلة المولية 159.62 g/mol","7.98 g","0.0783 mol","المقارنة: 12.5 g أكبر من المطلوب وتقابل مولات أكثر","تساوي نسبتي الكتلة والمولات (1.57)"]'::jsonb, '["الكتلة المولية = 63.55 + 32.07 + 64.00 = 159.62 g/mol","(أ) 0.0500 mol × 159.62 g/mol = 7.98 g","(ب) 12.5 g × (1 mol / 159.62 g) = 0.0783 mol","(ج) 12.5 / 7.98 = 1.57 و0.0783 / 0.0500 = 1.57، فالحسابان متسقان"]'::jsonb, '[{"element":"الكتلة المولية 159.62 g/mol","marks":1},{"element":"الكتلة 7.98 g","marks":1},{"element":"عدد المولات 0.0783 mol","marks":1},{"element":"المقارنة والاستنتاج باتساق الحسابين","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"الحسابات الثلاثة صحيحة مع مقارنة واستنتاج صحيحين"},{"level":"3–4 درجات","description":"الحسابات صحيحة مع نقص في المقارنة، أو خطأ في أحد الحسابين"},{"level":"1–2 درجة","description":"حساب الكتلة المولية أو أحد التحويلين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال كتلة Cu وحدها بدل الكتلة المولية للمركب","استعمال عامل التحويل المقلوب في الجزء (ب)","الاكتفاء بمقارنة الأرقام دون ربطها بالتناسب بين الكتلة والمولات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.493Z"}'::jsonb)
