('mcq', 3, 'لا يحتوي المركب (NH₄)₃PO₄ على أي فلز، ومع ذلك يُصنَّف مركبًا أيونيًّا. ما سبب ذلك؟', null, '["يتكون من أيوني NH₄⁺ و PO₄³⁻ المرتبطين بتجاذب كهربائي","يحتوي عددًا كبيرًا من الذرات (20 ذرة في وحدة الصيغة)","يحتوي ذرات هيدروجين وأكسجين مرتبطة معًا","يذوب في الماء، وكل مركب يذوب في الماء أيوني"]'::jsonb, 'تحليل', 'تعليل تصنيف مركب أيوني خالٍ من الفلز', 'صعب', 'الكتاب ص 170 — تصنيف المركبات (س36)'),
('mcq', 4, 'أيّ العبارات الآتية صحيحة؟', null, '["مول واحد من CaCl₂ يحتوي 6.02 × 10²³ جزيء من CaCl₂","مول واحد من C₂H₅OH يحتوي 6.02 × 10²³ وحدة صيغة من C₂H₅OH","مول واحد من CO₂ يحتوي 6.02 × 10²³ جزيء من CO₂","مول واحد من NaCl يحتوي 6.02 × 10²³ جزيء من NaCl"]'::jsonb, 'فهم', 'ربط نوع المركب بالجسيم الممثل', 'متوسط', 'الكتاب ص 168، 173 — الجسيم الممثل وعدد أفوجادرو'),
('mcq', 5, 'كُتبت تصنيفات لأربعة مركبات مع الجسيم الممثل لكل منها. أيّ الصفوف صحيح بالكامل (التصنيف والجسيم الممثل)؟', '{"headers":["الصف","المركب","التصنيف","الجسيم الممثل"],"rows":[["1","C₂H₅OH","جزيئي","جزيء"],["2","Na₂SO₄","جزيئي","جزيء"],["3","MgBr₂","أيوني","جزيء"],["4","HCN","أيوني","وحدة صيغة"]]}'::jsonb, '["الصف 1","الصف 2","الصف 3","الصف 4"]'::jsonb, 'تحليل', 'فحص تصنيفات في جدول', 'متوسط', 'الكتاب ص 170، 172 — تصنيف المركبات (س36، س41)'),
('mcq', 6, 'حسب طالب عدد الجسيمات في 5.84 g من NaCl (الكتلة المولية 58.44 g/mol) فوجد 6.02 × 10²² جزيء من NaCl. ما تقويمك لإجابته؟', null, '["الإجابة صحيحة، فالمركب الأيوني يتكون من جزيئات NaCl","الخطأ في عدد أفوجادرو لأنه لا يُستعمل مع المركبات الأيونية","الخطأ في الكتلة المولية لأن عليه استعمال كتلة Na وحدها","العدد صحيح لكن NaCl أيوني، فوحدته وحدة صيغة لا جزيء"]'::jsonb, 'تقويم', 'تقويم حل طالب بالمفاهيم', 'صعب', 'الكتاب ص 173–174 — الجسيم الممثل ووحدة الصيغة'),
('mcq', 7, 'أيّ الأزواج الآتية يتكون كل مركب فيه من أيونات (أيوني)؟', null, '["CCl₄ و CaCl₂","HCN و KC₂H₃O₂","NaCl و NH₄NO₃","C₁₂H₂₂O₁₁ و Sr(NO₃)₂"]'::jsonb, 'تحليل', 'تصنيف أزواج من المركبات', 'متوسط', 'الكتاب ص 170، 172 — تصنيف المركبات (س34، س35، س36)'),
('essay', 1, 'صنّف كلًّا من المركبات الآتية جزيئيًّا أو أيونيًّا، وحدّد جسيمه الممثل، ثم احسب كتلته المولية: (أ) Sr(NO₃)₂، (ب) (NH₄)₃PO₄، (ج) C₁₂H₂₂O₁₁. (الكتلة المولية: Sr = 87.62 g/mol، N = 14.01 g/mol، H = 1.008 g/mol، P = 30.97 g/mol، O = 16.00 g/mol، C = 12.01 g/mol)', null, null, 'تحليل', 'تصنيف وتحديد الجسيم الممثل وحساب الكتلة المولية', 'سهل', 'الكتاب ص 170 — تصنيف المركبات وحساب كتلتها المولية (س36)'),
('essay', 2, 'قارن بين 0.100 mol من CaCl₂ و0.100 mol من CCl₄ من حيث: نوع كل مركب، والجسيم الممثل وعدده، وعدد الأيونات أو الذرات الكلي في كل عينة. (عدد أفوجادرو 6.02 × 10²³)', null, null, 'تحليل', 'مقارنة مركبين من نوعين مختلفين', 'متوسط', 'الكتاب ص 173–174 — الجسيم الممثل وعدد أفوجادرو (مثال 5-9)'),
('essay', 3, 'قال طالب: «بما أن NaCl لا يتكون من جزيئات، فلا يمكن حساب كتلته المولية». قوّم هذه العبارة موضحًا الصواب. ثم احسب الكتلة المولية لكل من NaCl وCO₂، وعدد الجسيمات الممثلة (مع تسميتها) في 0.500 mol من كل منهما. (الكتلة المولية: Na = 22.99 g/mol، Cl = 35.45 g/mol، C = 12.01 g/mol، O = 16.00 g/mol، وعدد أفوجادرو 6.02 × 10²³)', null, null, 'تقويم', 'تقويم عبارة وتطبيقها حسابيًّا', 'صعب', 'الكتاب ص 170–174 — تصنيف المركبات والكتلة المولية')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
