from (values
('mcq', 1, 1, 'AlCl₃ مركب أيوني يتكون من أيونات Al³⁺ و Cl⁻ بنسبة 1 : 3، ولا يتكون من جزيئات منفصلة. أصغر وحدة تعبّر عن نسبة أيوناته هي وحدة الصيغة، فهي الجسيم الممثل، وهو الخيار «وحدة صيغة AlCl₃».', '["الجزيء هو الجسيم الممثل للمركبات الجزيئية فقط، وAlCl₃ مركب أيوني لا جزيئات فيه.","","الذرة هي الجسيم الممثل للعناصر، أما AlCl₃ فمركب لا يُمثَّل بذرة واحدة.","أيون Cl⁻ جزء من وحدة الصيغة وليس المركب كله؛ فالجسيم الممثل يعبّر عن النسبة بين الأيونات (1 : 3)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:32:48.493Z"}'::jsonb),
('mcq', 2, 3, 'C₁₂H₂₂O₁₁ (السكروز) يتكون من ذرات لافلزات (C وH وO) مرتبطة بروابط تساهمية، فهو مركب جزيئي جسيمه الممثل جزيء. أما Sr(NO₃)₂ وK₂CrO₄ فيحويان فلزًا وأيونًا سالبًا متعدد الذرات، و(NH₄)₃PO₄ يتكون من أيوني NH₄⁺ و PO₄³⁻؛ فكلها أيونية وجسيمها الممثل وحدة صيغة.', '["Sr(NO₃)₂ مركب أيوني من أيونات Sr²⁺ و NO₃⁻، فجسيمه الممثل وحدة صيغة.","(NH₄)₃PO₄ مركب أيوني من أيونات NH₄⁺ و PO₄³⁻ رغم خلوّه من فلز، فجسيمه الممثل وحدة صيغة.","K₂CrO₄ مركب أيوني من أيونات K⁺ و CrO₄²⁻، فجسيمه الممثل وحدة صيغة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:32:48.493Z"}'::jsonb),
('mcq', 3, 0, 'يتكون (NH₄)₃PO₄ من أيونات متعددة الذرات: NH₄⁺ موجب وPO₄³⁻ سالب، يرتبطان بقوى تجاذب كهربائي، فهو أيوني رغم خلوّه من فلز، وجسيمه الممثل وحدة صيغة.', '["","عدد الذرات لا يحدد نوع المركب؛ فالسكروز جزيئي ويحتوي 45 ذرة.","ذرات H وO في (NH₄)₃PO₄ ليست مرتبطة معًا (H مرتبط بـ N وO مرتبط بـ P)، ووجودهما في مركب لا يحدد نوعه؛ فهما موجودان أيضًا في أيونات مثل OH⁻.","الذوبان في الماء لا يكفي لتحديد النوع؛ فالسكروز مركب جزيئي يذوب في الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-18T03:32:48.493Z"}'::jsonb),
('mcq', 4, 2, 'CO₂ مركب جزيئي يتكون من جزيئات منفصلة، فمول واحد منه يحتوي عدد أفوجادرو من الجزيئات (6.02 × 10²³ جزيء). أما المركبات الأيونية (CaCl₂ وNaCl) فجسيمها الممثل وحدة صيغة، والمركبات الجزيئية (C₂H₅OH وCO₂) جسيمها الممثل جزيء. العبارة الصحيحة هي الثالثة.', '["CaCl₂ مركب أيوني لا يتكون من جزيئات؛ المول منه يحتوي 6.02 × 10²³ وحدة صيغة.","C₂H₅OH مركب جزيئي؛ المول منه يحتوي 6.02 × 10²³ جزيء لا وحدة صيغة.","","NaCl مركب أيوني لا يتكون من جزيئات؛ المول منه يحتوي 6.02 × 10²³ وحدة صيغة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:32:48.494Z"}'::jsonb),
('mcq', 5, 0, 'C₂H₅OH مركب جزيئي من لافلزات، وجسيمه الممثل جزيء؛ فالصف 1 صحيح بالكامل. Na₂SO₄ أيوني (Na⁺ وSO₄²⁻) وجسيمه وحدة صيغة، وMgBr₂ أيوني وجسيمه وحدة صيغة لا جزيء، وHCN جزيئي (لافلزات) وجسيمه جزيء لا وحدة صيغة.', '["","Na₂SO₄ مركب أيوني (فلز مع أيون متعدد الذرات)، فتصنيفه وجسيمه في الصف 2 خاطئان.","تصنيف MgBr₂ (أيوني) صحيح، لكن جسيمه الممثل وحدة صيغة لا جزيء.","HCN مركب جزيئي يتكون من لافلزات، فتصنيفه وجسيمه (وحدة صيغة) في الصف 4 خاطئان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-18T03:32:48.494Z"}'::jsonb),
('mcq', 6, 3, '5.84 g × (1 mol / 58.44 g) = 0.100 mol، ثم 0.100 × 6.02 × 10²³ = 6.02 × 10²². العدد صحيح، لكن NaCl مركب أيوني لا يتكون من جزيئات، فيُعبَّر عنه بـ 6.02 × 10²² وحدة صيغة.', '["المركب الأيوني يتكون من أيونات مرتبة في شبكة، ولا توجد فيه جزيئات NaCl منفصلة.","عدد أفوجادرو يُستعمل مع أي نوع من الجسيمات الممثلة، سواء أكانت جزيئات أم وحدات صيغة أم ذرات أم أيونات.","الكتلة المولية لـ NaCl تشمل Na وCl معًا (58.44 g/mol)، وقد استعملها الطالب استعمالًا صحيحًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-18T03:32:48.494Z"}'::jsonb),
('mcq', 7, 2, 'NaCl يتكون من Na⁺ و Cl⁻، وNH₄NO₃ من NH₄⁺ و NO₃⁻؛ فكلاهما أيوني، وهو الزوج الثالث. في بقية الأزواج مركب جزيئي واحد على الأقل: CCl₄ وHCN وC₁₂H₂₂O₁₁.', '["CCl₄ مركب جزيئي من لافلزات، وإن كان CaCl₂ أيونيًّا.","HCN مركب جزيئي من لافلزات، وإن كان KC₂H₃O₂ أيونيًّا.","","C₁₂H₂₂O₁₁ (السكروز) مركب جزيئي، وإن كان Sr(NO₃)₂ أيونيًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:32:48.494Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) Sr(NO₃)₂ أيوني (Sr²⁺ و NO₃⁻)، جسيمه الممثل وحدة صيغة؛ كتلته المولية = 87.62 + 2 × 14.01 + 6 × 16.00 = 87.62 + 28.02 + 96.00 = 211.64 g/mol. (ب) (NH₄)₃PO₄ أيوني (NH₄⁺ و PO₄³⁻)، جسيمه الممثل وحدة صيغة؛ كتلته المولية = 3 × 14.01 + 12 × 1.008 + 30.97 + 4 × 16.00 = 149.10 g/mol. (ج) C₁₂H₂₂O₁₁ جزيئي (لافلزات)، جسيمه الممثل جزيء؛ كتلته المولية = 12 × 12.01 + 22 × 1.008 + 11 × 16.00 = 342.30 g/mol.', '["Sr(NO₃)₂ أيوني، وحدة صيغة، 211.64 g/mol","(NH₄)₃PO₄ أيوني (أيون أمونيوم)، وحدة صيغة، 149.10 g/mol","C₁₂H₂₂O₁₁ جزيئي، جزيء، 342.30 g/mol","تعليل التصنيف بنوع العناصر أو الأيونات"]'::jsonb, '["Sr(NO₃)₂: فلز + أيون نترات → أيوني؛ 87.62 + 28.02 + 96.00 = 211.64 g/mol","(NH₄)₃PO₄: أيونا NH₄⁺ و PO₄³⁻ → أيوني؛ 42.03 + 12.096 + 30.97 + 64.00 = 149.096 ≈ 149.10 g/mol","C₁₂H₂₂O₁₁: لافلزات فقط → جزيئي؛ 144.12 + 22.176 + 176.00 = 342.296 ≈ 342.30 g/mol"]'::jsonb, '[{"element":"تصنيف Sr(NO₃)₂ وجسيمه وكتلته المولية","marks":2},{"element":"تصنيف (NH₄)₃PO₄ وجسيمه وكتلته المولية","marks":2},{"element":"تصنيف C₁₂H₂₂O₁₁ وجسيمه وكتلته المولية","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"تصنيف وجسيم وكتلة مولية صحيحة للمركبات الثلاثة مع تعليل"},{"level":"4–5 درجات","description":"مركبان صحيحان بالكامل مع خطأ في عنصر من الثالث"},{"level":"2–3 درجات","description":"مركب واحد صحيح بالكامل أو تصنيفات صحيحة دون حسابات"},{"level":"1 درجة","description":"تصنيف صحيح لمركب واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ (NH₄)₃PO₄ جزيئيًّا لأنه لا يحتوي فلزًا","تسمية جسيم المركب الأيوني جزيئًا","إهمال الرقم خارج القوس عند حساب الكتلة المولية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.495Z"}'::jsonb),
('essay', 2, null::int, null, null, 'CaCl₂ مركب أيوني (Ca²⁺ و Cl⁻)، جسيمه الممثل وحدة صيغة، وعددها = 0.100 × 6.02 × 10²³ = 6.02 × 10²² وحدة صيغة. تعطي كل وحدة 3 أيونات (1 Ca²⁺ و2 Cl⁻)، فالأيونات الكلية = 1.81 × 10²³. CCl₄ مركب جزيئي (لافلزات)، جسيمه الممثل جزيء، وعدده = 0.100 × 6.02 × 10²³ = 6.02 × 10²² جزيء. يحتوي كل جزيء 5 ذرات (1 C و4 Cl)، فالذرات الكلية = 3.01 × 10²³. لا تُحسب أيونات في CCl₄ لأنه لا يتكون من أيونات. وعدد الجسيمات الممثلة متساوٍ في العينتين لتساوي المولات.', '["CaCl₂ أيوني، CCl₄ جزيئي","الجسيم الممثل: وحدة صيغة لـ CaCl₂ وجزيء لـ CCl₄","6.02 × 10²² جسيمًا ممثلًا في كل عينة","1.81 × 10²³ أيون في CaCl₂","3.01 × 10²³ ذرة في CCl₄ ولا أيونات فيه"]'::jsonb, '["كل عينة 0.100 mol × 6.02 × 10²³ = 6.02 × 10²² جسيم ممثل","CaCl₂: 6.02 × 10²² وحدة صيغة × 3 أيونات = 1.81 × 10²³ أيون","CCl₄: 6.02 × 10²² جزيء × 5 ذرات = 3.01 × 10²³ ذرة"]'::jsonb, '[{"element":"تصنيف المركبين وتحديد الجسيم الممثل لكل منهما","marks":1},{"element":"عدد الجسيمات الممثلة 6.02 × 10²² لكل عينة","marks":1},{"element":"عدد الأيونات الكلي في CaCl₂","marks":1},{"element":"عدد الذرات الكلي في CCl₄","marks":1},{"element":"تعليل عدم وجود أيونات في CCl₄","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف وجسيمات وأعداد صحيحة مع التعليل"},{"level":"3–4 درجات","description":"تصنيف صحيح مع خطأ في أحد العددين أو غياب التعليل"},{"level":"1–2 درجة","description":"تصنيف صحيح أو عدد الجسيمات الممثلة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب عدد أيونات لمركب جزيئي مثل CCl₄","القول إن CaCl₂ يتكون من جزيئات","اعتبار عدد الجسيمات الممثلة في CaCl₂ هو عدد الأيونات نفسه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-18T03:32:48.495Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة خاطئة؛ فالكتلة المولية هي كتلة مول واحد من الجسيمات الممثلة، وتُحسب بجمع الكتل المولية للعناصر مضروبة في أعدادها في الصيغة سواء أكان المركب أيونيًّا أم جزيئيًّا. الفرق في تسمية الجسيم الممثل فقط: وحدة صيغة في NaCl، وجزيء في CO₂. الكتلة المولية لـ NaCl = 22.99 + 35.45 = 58.44 g/mol. الكتلة المولية لـ CO₂ = 12.01 + 2 × 16.00 = 44.01 g/mol. في 0.500 mol من NaCl: 0.500 × 6.02 × 10²³ = 3.01 × 10²³ وحدة صيغة. وفي 0.500 mol من CO₂: 3.01 × 10²³ جزيء.', '["العبارة خاطئة: الكتلة المولية تُحسب للمركبات الأيونية أيضًا","الجسيم الممثل يختلف: وحدة صيغة للأيوني وجزيء للجزيئي","58.44 g/mol لـ NaCl","44.01 g/mol لـ CO₂","3.01 × 10²³ وحدة صيغة من NaCl و3.01 × 10²³ جزيء من CO₂"]'::jsonb, '["NaCl: 22.99 + 35.45 = 58.44 g/mol","CO₂: 12.01 + 2 × 16.00 = 44.01 g/mol","NaCl: 0.500 mol × 6.02 × 10²³ = 3.01 × 10²³ وحدة صيغة","CO₂: 0.500 mol × 6.02 × 10²³ = 3.01 × 10²³ جزيء"]'::jsonb, '[{"element":"تخطئة العبارة مع تعليل صحيح","marks":1},{"element":"الكتلة المولية لـ NaCl","marks":1},{"element":"الكتلة المولية لـ CO₂","marks":1},{"element":"عدد الجسيمات في كل عينة","marks":1},{"element":"تسمية الجسيم الممثل بدقة (وحدة صيغة / جزيء)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تخطئة وتعليل صحيحان، وحسابات صحيحة، وتسمية دقيقة للجسيمين"},{"level":"3–4 درجات","description":"حسابات صحيحة مع نقص في التعليل أو التسمية"},{"level":"1–2 درجة","description":"حساب إحدى الكتلتين أو تخطئة دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين قابلية حساب الكتلة المولية ووجود الجزيئات","تسمية 3.01 × 10²³ جزيء NaCl","نسيان ضرب كتلة الأكسجين في 2 عند حساب CO₂"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.495Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
