select (select id from public.objectives where code = 'K1-C5-L3-O06'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'الكتلة المولية لكرومات البوتاسيوم K₂CrO₄ تساوي 194.20 g/mol، وهي مجموع 78.20 g من K و52.0 g من Cr و64.0 g من O. ما السبب العلمي لكون الكتلة المولية للمركب مجموع كتل عناصره؟', null, '["لأن الكتلة المولية للمركب تساوي متوسط الكتل المولية لعناصره","لأن كتلة المول من المركب هي كتلة ما فيه من مولات العناصر كلها، ولا تفنى كتلة عند اتحادها","لأن الكتلة تزداد عند اتحاد العناصر بسبب تكوّن الروابط بينها","لأن الكتلة تنقص عند اتحاد العناصر لتتكوّن مادة جديدة"]'::jsonb, 'فهم', 'تفسير علاقة الكتلة المولية بحفظ الكتلة', 'سهل', 'الكتاب ص 170 — الكتلة المولية للمركبات وقانون حفظ الكتلة'),
('mcq', 2, 'اتحد 2 mol من الصوديوم (كتلتها 45.98 g) مع 1 mol من غاز الكلور Cl₂ (كتلته 70.90 g) تمامًا لتكوين كلوريد الصوديوم NaCl. ما كتلة NaCl الناتج بحسب قانون حفظ الكتلة؟', null, '["58.44 g","70.90 g","24.92 g","116.88 g"]'::jsonb, 'تطبيق', 'تطبيق حفظ الكتلة على تفاعل اتحاد', 'متوسط', 'الكتاب ص 170 — الكتلة المولية للمركبات وقانون حفظ الكتلة'),
('mcq', 3, 'كل مول من كرومات البوتاسيوم K₂CrO₄ (194.20 g) أو كلوريد الصوديوم NaCl (58.44 g) أو السكروز C₁₂H₂₂O₁₁ (342.30 g) يحتوي العدد نفسه من الجسيمات الممثلة (6.02 × 10²³). ما سبب اختلاف كتلها المولية؟', null, '["لأن عدد الجسيمات في المول يختلف من مركب لآخر","لأن قانون حفظ الكتلة لا ينطبق على المركبات الأيونية","لأن لكل مركب أعدادًا وأنواعًا مختلفة من الذرات، فيختلف مجموع كتل عناصره","لأن كتلة الذرة الواحدة تتغير عند اتحادها في المركب"]'::jsonb, 'فهم', 'تفسير اختلاف الكتل المولية', 'متوسط', 'الكتاب ص 170 — شكل 10-5، الكتلة المولية للمركبات'),
('mcq', 4, 'قال طالب إن الكتلة المولية لـ H₂O تساوي متوسط الكتل المولية لعنصريه: (1.008 + 16.00) ÷ 2 = 8.504 g/mol. ما تقويمك لهذا الاستدلال؟', null, '["خطأ؛ لأن مول H₂O يحتوي 2 mol H و1 mol O، فكتلته مجموع كتلتيهما: 18.02 g/mol","صحيح؛ لأن الكتلة المولية للمركب متوسط الكتل المولية لعناصره","خطأ؛ لأن كتلة المركب تساوي كتلة العنصر الأثقل فيه فقط، أي 16.00 g/mol","خطأ؛ لأن كتلة O تُطرح منها كتلة H فتكون 14.99 g/mol"]'::jsonb, 'تحليل', 'تقويم استدلال خاطئ بحفظ الكتلة', 'صعب', 'الكتاب ص 170 — الكتلة المولية للمركبات وقانون حفظ الكتلة'),
('mcq', 5, 'ادّعى طالب أن 12.01 g من الكربون تتفاعل تمامًا مع 32.00 g من الأكسجين O₂ فتنتج 40.00 g من ثاني أكسيد الكربون CO₂. هل ادّعاؤه صحيح؟', null, '["نعم، لأن المركب الناتج يكون أخف من مجموع مكوناته","لا، لأن كتلة CO₂ الناتج يجب أن تساوي 44.01 g مجموع كتلتي المتفاعلين","نعم، لأن كتلة CO₂ تساوي كتلة الأكسجين المتفاعل مضافًا إليه 8 g","لا، لأن الكربون والأكسجين لا يتحدان لتكوين مركب"]'::jsonb, 'تقويم', 'تقويم ادعاء بحفظ الكتلة', 'صعب', 'الكتاب ص 170 — قانون حفظ الكتلة'),
('mcq', 6, 'الكتلة المولية لأكسيد الحديد III Fe₂O₃ تساوي 159.70 g/mol، وكتلة الحديد في مول واحد منه 111.70 g (2 × 55.85 g). ما كتلة الأكسجين في مول واحد من Fe₂O₃ بحسب قانون حفظ الكتلة؟', null, '["111.70 g","16.00 g","48.00 g","271.40 g"]'::jsonb, 'تطبيق', 'إيجاد كتلة مكوّن من كتلة المركب', 'متوسط', 'الكتاب ص 170 — الكتلة المولية للمركبات وقانون حفظ الكتلة'),
('mcq', 7, 'عند حساب الكتلة المولية لـ Ca(OH)₂ (74.10 g/mol) نضرب الكتلة المولية لكل عنصر في عدد مولاته في الصيغة ثم نجمع. لماذا نضرب قبل أن نجمع؟', null, '["لأن الأرقام السفلية في الصيغة تمثل كتل العناصر بالجرام","لأن قانون حفظ الكتلة يقتضي مضاعفة كتل جميع العناصر داخل الأقواس فقط","لأن الكتلة المولية للمركب تساوي متوسط الكتل المولية لعناصره","لأن مول المركب يحتوي عدة مولات من كل عنصر، وكتلته مجموع كتل جميعها"]'::jsonb, 'فهم', 'تفسير خطوات حساب الكتلة المولية', 'سهل', 'الكتاب ص 170 — الكتلة المولية للمركبات'),
('essay', 1, 'احسب الكتلة المولية لكرومات البوتاسيوم K₂CrO₄ من الكتل المولية: K = 39.10 g/mol، Cr = 52.0 g/mol، O = 16.0 g/mol، ثم فسّر بقانون حفظ الكتلة لماذا تساوي كتلة مول واحد من المركب مجموع كتل العناصر المكوّنة له.', null, null, 'فهم', 'حساب وتفسير بقانون', 'سهل', 'الكتاب ص 170 — الكتلة المولية للمركبات وقانون حفظ الكتلة'),
('essay', 2, 'يتفاعل الألومنيوم مع الكلور وفق المعادلة: 2Al + 3Cl₂ → 2AlCl₃. أثبت بالحسابات أن الكتلة محفوظة في هذا التفاعل، مستعملًا الكتل المولية: Al = 26.98 g/mol، Cl₂ = 70.90 g/mol، AlCl₃ = 133.33 g/mol، ثم بيّن علاقة ذلك بحساب الكتلة المولية لـ AlCl₃.', null, null, 'تطبيق', 'إثبات حفظ الكتلة بالحساب', 'متوسط', 'الكتاب ص 170 — الكتلة المولية للمركبات وقانون حفظ الكتلة'),
('essay', 3, '(أ) فسّر لماذا تختلف الكتلة المولية لكل من NaCl (58.44 g/mol) وK₂CrO₄ (194.20 g/mol) والسكروز C₁₂H₂₂O₁₁ (342.30 g/mol) مع أن المول من كل منها يحتوي عدد أفوجادرو من الجسيمات الممثلة. (ب) هل يمكن أن تكون الكتلة المولية لمركب أقل من الكتلة المولية لأحد عناصره؟ فسّر مستدلًّا بالمركب CO₂ (C = 12.01 g/mol، O = 16.00 g/mol، CO₂ = 44.01 g/mol).', null, null, 'تحليل', 'تفسير ومقارنة واستدلال', 'صعب', 'الكتاب ص 170 — شكل 10-5، قانون حفظ الكتلة')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K1-C5-L3-O06') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'وفق قانون حفظ الكتلة لا تفنى كتلة ولا تُستحدث عند اتحاد العناصر؛ فمول K₂CrO₄ يتكون من 2 mol K و1 mol Cr و4 mol O، وكتلته هي مجموع كتل هذه المولات (78.20 + 52.0 + 64.0 = 194.20 g).', '["المتوسط لا يعبّر عن كتلة كل ما في المول؛ فالمركب يحوي عدة مولات من العناصر، وكتلته مجموع كتلها لا متوسطها.","","لا تزداد الكتلة عند الاتحاد؛ فقانون حفظ الكتلة يقتضي أن تبقى الكتلة الكلية ثابتة.","لا تنقص الكتلة عند الاتحاد؛ فكتلة المركب تساوي كتلة المواد التي تكوّن منها تمامًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-18T03:32:48.496Z"}'::jsonb),
('mcq', 2, 3, 'كتلة الناتج تساوي كتلة المتفاعلات: 45.98 g + 70.90 g = 116.88 g. وهذه تساوي أيضًا كتلة 2 mol من NaCl (2 × 58.44 g = 116.88 g). والخيار الصحيح هو «116.88 g».', '["هذه كتلة مول واحد من NaCl فقط، بينما الناتج 2 mol من NaCl.","هذه كتلة الكلور وحده؛ ولم تُضَف إليها كتلة الصوديوم.","هذا الناتج (70.90 - 45.98) طرح الكتلتين؛ والكتلة لا تفنى بل تُجمع كتل المتفاعلات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-18T03:32:48.496Z"}'::jsonb),
('mcq', 3, 2, 'الكتلة المولية للمركب مجموع كتل جميع مولات العناصر في مول واحد منه، وهذه تختلف باختلاف أنواع الذرات وأعدادها في الصيغة (مثلًا يحوي السكروز 45 ذرة في كل وحدة بينما يحوي NaCl ذرتين فقط). لذا يختلف المجموع وتختلف الكتل المولية.', '["عدد الجسيمات في المول ثابت (عدد أفوجادرو) لجميع المواد، وليس سبب الاختلاف.","قانون حفظ الكتلة ينطبق على جميع التفاعلات والمركبات الأيونية وغيرها.","","كتلة الذرة لا تتغير باتحادها؛ ولو تغيرت لما بقيت الكتلة محفوظة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:32:48.496Z"}'::jsonb),
('mcq', 4, 0, 'مول H₂O يتكون من 2 mol ذرات H و1 mol ذرات O، ولا تفنى كتلة أي منها عند اتحادها، فكتلته = 2 × 1.008 + 16.00 = 18.02 g/mol (مجموع الكتل لا متوسطها). والخيار الصحيح هو الأول.', '["","المتوسط لا يعبّر عن الكتلة الفعلية؛ فمول الماء يحوي كتلتي عنصريه كلتيهما لا متوسطهما.","كتلة H لا تُهمل؛ فالمركب يحتوي كتلة جميع عناصره، لا كتلة الأثقل منها فقط.","الكتلة لا تُطرح عند تكوين المركب؛ فالاتحاد يجمع الكتل لا يطرحها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-18T03:32:48.497Z"}'::jsonb),
('mcq', 5, 1, 'وفق قانون حفظ الكتلة كتلة الناتج = كتلة المتفاعلات = 12.01 + 32.00 = 44.01 g، وهي تساوي الكتلة المولية لـ CO₂. فالقيمة 40.00 g تعني فقدان 4.01 g من الكتلة وهو غير ممكن. الخيار الصحيح هو الثاني.', '["المركب لا يكون أخف من مكوناته؛ فالكتلة محفوظة عند التفاعل.","","لا أساس لإضافة 8 g؛ والمعيار هو مجموع كتلتي المتفاعلين (44.01 g).","الكربون والأكسجين يتحدان فعلًا لتكوين CO₂؛ والخطأ في الكتلة المنسوبة للناتج لا في إمكان التفاعل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-18T03:32:48.497Z"}'::jsonb),
('mcq', 6, 2, 'كتلة المركب = مجموع كتل عناصره، فكتلة الأكسجين = 159.70 g − 111.70 g = 48.00 g، وهي تطابق 3 mol من الأكسجين (3 × 16.00 g). الخيار الصحيح «48.00 g».', '["هذه كتلة الحديد، لا كتلة الأكسجين.","هذه كتلة مول واحد من ذرات الأكسجين، بينما يحتوي مول Fe₂O₃ 3 mol من الأكسجين.","","هذا الناتج (159.70 + 111.70) جمع كتلتي المركب والحديد؛ والمركب هو المجموع أصلًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-18T03:32:48.497Z"}'::jsonb),
('mcq', 7, 3, 'الأرقام في الصيغة تدل على عدد مولات كل عنصر في مول واحد من المركب (1 mol Ca و2 mol O و2 mol H). وبحفظ الكتلة تكون كتلة المول مجموع كتل هذه المولات، فنضرب كتلة كل عنصر في عدد مولاته قبل الجمع: 40.08 + 2 × 16.00 + 2 × 1.008 = 74.10 g/mol. والخيار الصحيح هو الأخير.', '["الأرقام السفلية تدل على عدد المولات (أو الذرات) لا على الكتل بالجرام.","لا يقتصر الضرب على ما داخل الأقواس؛ فكل عنصر تُضرب كتلته المولية في عدد مولاته في الصيغة.","المتوسط لا يمثل كتلة جميع ما في مول المركب؛ فالكتلة مجموع كتل مولات العناصر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-18T03:32:48.497Z"}'::jsonb),
('essay', 1, null::int, null, null, 'في مول K₂CrO₄ يوجد 2 mol K و1 mol Cr و4 mol O. كتلة K = 2 × 39.10 = 78.20 g، وكتلة Cr = 52.0 g، وكتلة O = 4 × 16.0 = 64.0 g. الكتلة المولية = 78.20 + 52.0 + 64.0 = 194.20 g/mol. التفسير: ينص قانون حفظ الكتلة على أن الكتلة لا تفنى ولا تُستحدث في التفاعل الكيميائي، فعند اتحاد العناصر لتكوين المركب تساوي كتلة المركب الناتج كتلة المتفاعلات (العناصر) مجتمعة؛ ولذلك تكون كتلة مول المركب مجموع كتل مولات عناصره.', '["2 mol K و1 mol Cr و4 mol O","78.20 + 52.0 + 64.0","194.20 g/mol","الكتلة محفوظة: كتلة المركب الناتج = كتلة المتفاعلات","ربط الجمع بقانون حفظ الكتلة"]'::jsonb, '["كتلة K = 2 mol × 39.10 g/mol = 78.20 g","كتلة Cr = 1 mol × 52.0 g/mol = 52.0 g","كتلة O = 4 mol × 16.0 g/mol = 64.0 g","الكتلة المولية = 78.20 + 52.0 + 64.0 = 194.20 g/mol"]'::jsonb, '[{"element":"حساب كتل العناصر الثلاثة","marks":1},{"element":"الكتلة المولية 194.20 g/mol","marks":1},{"element":"نص قانون حفظ الكتلة بما يناسب التفاعل","marks":1},{"element":"ربط مجموع الكتل بالقانون","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حساب صحيح للكتلة المولية مع تفسير دقيق بحفظ الكتلة"},{"level":"2–3 درجات","description":"حساب صحيح مع تفسير ناقص، أو تفسير صحيح مع خطأ في الحساب"},{"level":"1 درجة","description":"ذكر القانون أو حساب جزء من الكتلة المولية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر القانون دون ربطه بجمع الكتل في المركب","حساب الكتلة المولية بحساب متوسط كتل العناصر","نسيان ضرب كتلة O في 4 أو كتلة K في 2"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-18T03:32:48.498Z"}'::jsonb),
('essay', 2, null::int, null, null, 'كتلة المتفاعلات: 2 mol Al = 2 × 26.98 = 53.96 g؛ 3 mol Cl₂ = 3 × 70.90 = 212.70 g؛ المجموع = 53.96 + 212.70 = 266.66 g. كتلة الناتج: 2 mol AlCl₃ = 2 × 133.33 = 266.66 g. الكتلتان متساويتان، فالكتلة محفوظة. والعلاقة بحساب الكتلة المولية: كتلة مول AlCl₃ = 133.33 g = 26.98 g (1 mol Al) + 106.35 g (3 mol Cl)؛ أي إن الكتلة المولية للمركب مجموع كتل عناصره، وهذا نتيجة حفظ الكتلة عند اتحادها.', '["كتلة المتفاعلات 266.66 g","كتلة الناتج 266.66 g","تساوي الكتلتين يثبت حفظ الكتلة","133.33 = 26.98 + 106.35","الكتلة المولية للمركب مجموع كتل عناصره بسبب حفظ الكتلة"]'::jsonb, '["كتلة 2 mol Al = 2 × 26.98 = 53.96 g","كتلة 3 mol Cl₂ = 3 × 70.90 = 212.70 g","كتلة المتفاعلات = 53.96 + 212.70 = 266.66 g","كتلة 2 mol AlCl₃ = 2 × 133.33 = 266.66 g","26.98 + 3 × 35.45 = 133.33 g/mol لـ AlCl₃"]'::jsonb, '[{"element":"كتلة المتفاعلات 266.66 g","marks":1},{"element":"كتلة الناتج 266.66 g","marks":1},{"element":"الاستنتاج: الكتلة محفوظة","marks":1},{"element":"ربطه بالكتلة المولية للمركب كمجموع كتل العناصر","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حساب الكتلتين صحيح، واستنتاج صحيح، وربط بالكتلة المولية"},{"level":"2–3 درجات","description":"حساب صحيح مع نقص في الاستنتاج أو الربط"},{"level":"1 درجة","description":"حساب كتلة المتفاعلات أو الناتج فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال المعاملات (2 و3) عند حساب الكتل","استعمال كتلة Cl بدل كتلة Cl₂ لثلاثة مولات","ذكر التساوي دون الربط بالقانون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-18T03:32:48.498Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) عدد الجسيمات الممثلة في المول ثابت (6.02 × 10²³)، لكن كل جسيم ممثل يتكون من أعداد وأنواع مختلفة من الذرات: وحدة NaCl فيها ذرتان (Na و Cl)، ووحدة K₂CrO₄ فيها 7 ذرات، وجزيء السكروز فيه 45 ذرة؛ وبحفظ الكتلة تكون الكتلة المولية مجموع كتل مولات جميع العناصر في المول، فتختلف باختلاف أعداد الذرات وأنواعها. (ب) لا يمكن؛ لأن كتلة مول المركب تضم كتل جميع عناصره، فهي أكبر من كتلة أي عنصر منفرد فيه. ففي CO₂: 44.01 g/mol = 12.01 (من C) + 32.00 (من 2 mol O)، وهي أكبر من 12.01 g/mol للكربون ومن 16.00 g/mol للأكسجين. ولو كانت أقل لفُقدت كتلة عند التفاعل، وهذا يخالف قانون حفظ الكتلة.', '["عدد الجسيمات الممثلة في المول ثابت","اختلاف أعداد وأنواع الذرات في الجسيم الممثل","الكتلة المولية مجموع كتل العناصر بحفظ الكتلة","لا يمكن أن تكون أقل من كتلة أحد عناصره","مثال CO₂: 44.01 = 12.01 + 32.00 أكبر من 12.01 ومن 16.00"]'::jsonb, '["NaCl: وحدة الصيغة فيها ذرتان؛ K₂CrO₄: 7 ذرات؛ السكروز: 45 ذرة","الكتلة المولية = مجموع كتل مولات العناصر، فتختلف باختلاف ذلك","CO₂: 12.01 + 2 × 16.00 = 44.01 g/mol","44.01 أكبر من 12.01 ومن 16.00، فلا يمكن أن تكون الكتلة المولية للمركب أقل من كتلة أحد عناصره"]'::jsonb, '[{"element":"ثبات عدد الجسيمات في المول","marks":1},{"element":"اختلاف أعداد وأنواع الذرات يفسر اختلاف الكتل المولية","marks":1},{"element":"الربط بحفظ الكتلة (الجمع)","marks":1},{"element":"الإجابة بعدم إمكان كون الكتلة المولية للمركب أقل من كتلة أحد عناصره","marks":1},{"element":"الاستدلال بمثال CO₂ بالأرقام","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تفسير كامل للجزأين مع ربط بحفظ الكتلة واستدلال رقمي بـ CO₂"},{"level":"3–4 درجات","description":"تفسير صحيح لأحد الجزأين مع نقص في الآخر"},{"level":"1–2 درجة","description":"ذكر فكرة واحدة صحيحة دون تفسير كاف"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن عدد الجسيمات في المول يختلف من مادة لأخرى","عدّ الكتلة المولية للمركب متوسطًا لكتل عناصره","الاستدلال بـ CO₂ دون ذكر مجموع الكتل (12.01 + 32.00)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-18T03:32:48.499Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
